(async () => {
  const id = 'ml-dark-inject';
  document.getElementById(id)?.remove();
  const s = document.createElement('style');
  s.id = id;
  s.textContent = "/* ===== tokens.css ===== */\n/* ============================================================================\n   tokens.css — single source of truth for the palette.\n   Change a value here and the whole theme follows.\n   In the UserCSS build every token below is also exposed as an @var.\n   ========================================================================== */\n\n:root {\n  /* ---- surfaces: low-chroma blue-grey ramp, never pure black ------------ */\n  --ml-surface-0: #12151a; /* page background                        */\n  --ml-surface-1: #181c22; /* cards, panels                          */\n  --ml-surface-2: #1f242c; /* inputs, chips, hover                   */\n  --ml-surface-3: #262c35; /* popovers, dropdowns, tooltips          */\n  --ml-surface-4: #2e3540; /* modals, top-most layer                 */\n\n  /* ---- text ------------------------------------------------------------ */\n  --ml-text-primary: #e3e8ef;   /* never #fff: avoids halation        */\n  --ml-text-secondary: #a9b3c1; /* was rgba(0,0,0,.55)                */\n  --ml-text-muted: #7c8794;     /* was #666 / #737373                 */\n  /* Facet/sidebar text: 13-14px regular weight on the page tone needs more\n     luminance than --ml-text-secondary to stay comfortable. Reported as\n     \"las letras apenas se leen\" in the listing filter column. */\n  --ml-text-facet: #c2cbdb;\n  --ml-text-disabled: #5a6472;  /* was #999: placeholders             */\n  --ml-text-on-brand: #f2f5f8;  /* text over brand fills              */\n\n  /* ---- borders --------------------------------------------------------- */\n  --ml-border-subtle: #242a33;  /* was #ededed (dividers)             */\n  --ml-border: #2f3742;         /* was #d5d9d9 (inputs, outlines)     */\n  --ml-border-strong: #3d4653;  /* was rgba(0,0,0,.1)                 */\n\n  /* ---- brand + semantic ------------------------------------------------ */\n  --ml-green: #34d17a;          /* was #00a650, lightened for text    */\n  --ml-green-fill: #00a650;     /* keep brand fills                   */\n  --ml-green-tint: #14261d;     /* was rgb(229,246,237)               */\n  --ml-blue: #5b9bff;           /* was #3483fa, lightened for text    */\n  --ml-blue-fill: #3483fa;      /* keep brand fills                   */\n  --ml-blue-tint: rgba(91, 155, 255, 0.12); /* was rgba(65,137,230,.1) */\n  --ml-blue-tint-strong: rgba(91, 155, 255, 0.2);\n  --ml-blue-vivid: #6b6bff;     /* was #1717ff                        */\n  --ml-yellow: #ffe600;         /* brand; dark text on it             */\n  --ml-yellow-soft: #ffec7a;    /* was #fff059                        */\n  --ml-red: #ff6b7a;            /* text use                           */\n  --ml-red-fill: #d92f41;       /* fill use                           */\n  --ml-red-tint: #3a1219;\n  --ml-pink: #ff4d94;           /* was #e60063                        */\n  --ml-pink-tint: #33202a;      /* was rgb(255,238,245)               */\n  --ml-orange: #ff8a4c;         /* was rgb(255,119,51) / rgb(230,84,11) */\n  --ml-peach-tint: #3a2a22;     /* was rgb(255,228,214)               */\n  --ml-indigo: #8b90ff;         /* was rgb(67,76,228)                 */\n  --ml-lavender-tint: #171a21;  /* was rgb(231,233,243) seller hub    */\n\n  /* ---- effects --------------------------------------------------------- */\n  --ml-overlay: rgba(6, 8, 11, 0.72);\n  --ml-scrim: rgba(6, 8, 11, 0.55);\n  --ml-shadow-card: 0 1px 2px rgba(0, 0, 0, 0.5);\n  --ml-shadow-pop: 0 8px 24px rgba(0, 0, 0, 0.6);\n  --ml-img-dim: 0.88; /* brightness applied to product photos           */\n}\n\n/* ===== base.css ===== */\n/* ============================================================================\n   base.css — document level: native dark affordances, page/window surfaces,\n   media protection, safety net for inline light backgrounds.\n   ========================================================================== */\n\n/* Native UI (scrollbars, selects, date pickers, spinners) turns dark.\n   This is the single cheapest durability win in the whole theme. */\nhtml {\n  color-scheme: dark !important;\n  background-color: var(--ml-surface-0) !important;\n}\n\nbody,\n#root-app,\n#nav-header,\ndiv[role=\"main\"],\nmain {\n  background-color: var(--ml-surface-0) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n::selection {\n  background-color: var(--ml-blue-fill);\n  color: var(--ml-text-on-brand);\n}\n\n/* Focus must stay visible on dark: MELI ships rgba(0,0,0,.1) outlines. */\n:focus-visible {\n  outline: 2px solid var(--ml-blue) !important;\n  outline-offset: 1px !important;\n}\n\n/* Scrollbars */\n::-webkit-scrollbar {\n  width: 12px;\n  height: 12px;\n}\n::-webkit-scrollbar-track {\n  background: var(--ml-surface-0);\n}\n::-webkit-scrollbar-thumb {\n  background: var(--ml-border-strong);\n  border: 3px solid var(--ml-surface-0);\n  border-radius: 8px;\n}\n::-webkit-scrollbar-thumb:hover {\n  background: #4a5464;\n}\n::-webkit-scrollbar-corner {\n  background: var(--ml-surface-0);\n}\n\n/* Chrome autofill bleeds white; kill it explicitly. */\ninput:-webkit-autofill,\ninput:-webkit-autofill:hover,\ninput:-webkit-autofill:focus,\ntextarea:-webkit-autofill,\nselect:-webkit-autofill {\n  -webkit-text-fill-color: var(--ml-text-primary) !important;\n  -webkit-box-shadow: 0 0 0 1000px var(--ml-surface-2) inset !important;\n  caret-color: var(--ml-text-primary);\n}\n\n/* ---------------------------------------------------------------------------\n   Media protection. Product photos, ads and video keep their own colours.\n   They are only dimmed globally by --ml-img-dim (0.9 by default) so white\n   studio backgrounds stop being headlights, then framed on a dark surface.\n   ------------------------------------------------------------------------- */\nimg.poly-component__picture,\n.ui-pdp-gallery__figure img,\n.ui-pdp-image,\n.ui-pdp-thumbnail img,\n.ui-pdp-gallery__figure,\n.cl-image-label img,\n.ui-search-carousel__item-generic-card img,\n.bads-vertical-product-card__image-container img,\n.poly-card__portada img {\n  filter: brightness(var(--ml-img-dim));\n}\n\n/* Brand marks stay untouched — a dimmed logo looks broken. */\n.nav-logo img,\n.nav-logo svg,\n.nav-header-avatar img,\n.user-menu__avatar,\n.nav-account-switcher__avatar {\n  filter: none !important;\n}\n\n/* Images used as CSS backgrounds (MELI widgets, third-party ad frames). */\n[style*=\"background-image\"] {\n  color-scheme: dark;\n}\n\n/* ---------------------------------------------------------------------------\n   Safety net for inline light backgrounds written by MELI widgets or by\n   third-party ad/chat scripts that we have not enumerated. Only literal\n   white inline backgrounds are caught, so brand fills are never harmed.\n   ------------------------------------------------------------------------- */\n[style*=\"background-color: rgb(255, 255, 255)\"],\n[style*=\"background-color: #fff\"],\n[style*=\"background-color:#fff\"],\n[style*=\"background: rgb(255, 255, 255)\"],\n[style*=\"background: #fff\"],\n[style*=\"background:#fff\"] {\n  background-color: var(--ml-surface-1) !important;\n}\n\n/* Same idea for inline dark text. */\n[style*=\"color: rgb(0, 0, 0)\"]:not([style*=\"background\"]) {\n  color: var(--ml-text-primary) !important;\n}\n[style*=\"color: rgba(0, 0, 0, 0.9)\"] {\n  color: var(--ml-text-primary) !important;\n}\n[style*=\"color: rgba(0, 0, 0, 0.55)\"] {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ===== 10-header.css ===== */\n/* ============================================================================\n   10-header.css — top navigation, search field, suggestions, user menu,\n   category mega-menu, footer. MELI's header is white (nav-header-plus) or\n   brand yellow depending on the variant; both become dark here.\n   ========================================================================== */\n\n.nav-header,\n.nav-header-plus,\n.nav-header-wrapper,\n#nav-header.nav-header-plus {\n  background-color: var(--ml-surface-1) !important;\n  border-bottom: 1px solid var(--ml-border-subtle) !important;\n  box-shadow: none !important;\n}\n\n/* The classic yellow band variant: keep a brand hint, but dark. */\n.nav-header:not(.nav-header-plus) {\n  background-color: var(--ml-surface-1) !important;\n}\n\n/* ---- search field ------------------------------------------------------- */\n.nav-search-input,\n.nav-search .nav-search-input {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border: 1px solid var(--ml-border) !important;\n  box-shadow: none !important;\n}\n.nav-search-input::placeholder {\n  color: var(--ml-text-disabled) !important;\n}\n.nav-search-btn,\n.nav-search .nav-icon-search,\nbutton.nav-search-btn {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* ---- search suggestions (opens under the field) ------------------------- */\n.sb-suggestions,\n.sb-suggestions__list,\n.sb-suggestions__item,\n.nav-search-suggestions {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n.sb-suggestions__item:hover,\n.sb-suggestions__item--highlighted {\n  background-color: var(--ml-surface-4) !important;\n}\n.sb-suggestions__item,\n.sb-suggestions__title {\n  color: var(--ml-text-primary) !important;\n}\n.sb-suggestions__footer,\n.sb-suggestions__hint {\n  color: var(--ml-text-muted) !important;\n}\n\n/* ---- category mega-menu ------------------------------------------------- */\n.nav-categs-detail,\n.nav-categs-detail__container,\n.nav-categs-detail__content,\n.nav-categs-detail .nav-categs-detail__item {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n.nav-categs-detail__title,\n.nav-categs-detail__link,\n.nav-categs-detail__item a {\n  color: var(--ml-text-primary) !important;\n}\n.nav-categs-detail__item:hover,\n.nav-categs-detail__link:hover {\n  background-color: var(--ml-surface-4) !important;\n  color: var(--ml-blue) !important;\n}\n\n/* ---- user dropdown ------------------------------------------------------ */\n.user-menu,\n.user-menu__one-column,\n.nav-header-user-layer,\n.nav-header-profile-evolution__container,\n.nav-account-switcher {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n  color: var(--ml-text-primary) !important;\n}\n.user-menu__item,\n.user-menu__link,\n.nav-menu-item-link,\n.nav-menu-link-cp,\n.nav-menu-categories-link,\n.option-purchases,\n.bookmarks-text {\n  color: var(--ml-text-primary) !important;\n}\n.user-menu__item:hover,\n.user-menu__link:hover,\n.nav-menu-item-link:hover,\n.option-purchases:hover {\n  background-color: var(--ml-surface-4) !important;\n}\n.user-menu__divider,\n.nav-menu-divider {\n  border-color: var(--ml-border-subtle) !important;\n}\n.user-menu__shortcuts-tag,\n.nav-link-tag {\n  background-color: var(--ml-blue-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n\n/* ---- header text, badges, cart ------------------------------------------ */\n.nav-header-username,\n.nav-menu-cp,\n.nav-menu-cp-logged,\n.nav-menu-cp-send,\n.nav-header-cp-anchor,\n.nav-header-user-myml {\n  color: var(--ml-text-primary) !important;\n}\n.nav-header-notifications-badge,\n.nav-cart .nav-header-notifications-badge {\n  background-color: var(--ml-blue-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n.nav-cart {\n  color: var(--ml-text-primary) !important;\n}\n.nav-cart:hover {\n  background-color: var(--ml-surface-2) !important;\n}\n\n/* ---- Icon font ---------------------------------------------------------\n   MELI's header icons are NOT svg: they are empty <i class=\"nav-icon-cart\">\n   elements whose glyph lives in ::before as a private-use codepoint\n   (e.g. content: \"\\ea1f\") and is painted with `color`. MELI's own rule wins\n   over a bare `.nav-cart` (element+class beats class), so the selector below\n   is element + class + attribute. Measured dark glyphs: nav-icon-search,\n   nav-menu-cp, nav-icon-notifications, nav-icon-cart, nav-icon-chevron-up. */\n.nav-header i[class^=\"nav-icon-\"],\n.nav-header i[class*=\" nav-icon-\"],\nheader i[class^=\"nav-icon-\"],\nheader i[class*=\" nav-icon-\"],\n.nav-header .nav-cart i,\n.nav-header .option-notifications i,\n/* Global fallback: every MELI icon-font glyph is a dark codepoint, so any of\n   them must be light regardless of which header variant renders it. */\ni[class^=\"nav-icon-\"],\ni[class*=\" nav-icon-\"] {\n  color: var(--ml-text-primary) !important;\n}\n/* MELI ALSO sets the colour on the pseudo-element itself, e.g.\n   `.nav-icon-cart:before { color: rgba(0,0,0,.898) }`. An !important on the\n   element does not reach it, so the glyph needs its own rule. `inherit`\n   keeps this generic: the glyph always follows whatever colour the element\n   resolved to, including the per-context overrides below. */\ni[class^=\"nav-icon-\"]::before,\ni[class*=\" nav-icon-\"]::before,\ni[class^=\"nav-icon-\"]::after,\ni[class*=\" nav-icon-\"]::after {\n  color: inherit !important;\n}\n.nav-header .nav-cart:hover i,\n.nav-header .option-notifications:hover i {\n  color: var(--ml-blue) !important;\n}\n/* The search magnifier sits on a raised field: keep it secondary, not white. */\n.nav-search i[class^=\"nav-icon-\"],\n.nav-search i[class*=\" nav-icon-\"],\n.nav-search .nav-icon-search {\n  color: var(--ml-text-secondary) !important;\n}\n/* Location pin + its label pulse on the left of the header. */\n.nav-header .nav-menu-cp,\n.nav-header .nav-menu-cp i,\n.nav-header .nav-header-cp-anchor {\n  color: var(--ml-text-primary) !important;\n}\n.shortcut-name,\n.shortcut-key {\n  color: var(--ml-text-primary) !important;\n}\n.shortcut-key {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* ---- footer ------------------------------------------------------------- */\n.nav-footer,\n.nav-footer-wrapper,\nfooter[role=\"contentinfo\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-top: 1px solid var(--ml-border-subtle) !important;\n}\n.nav-footer-title,\n.nav-footer-link,\n.nav-footer a {\n  color: var(--ml-text-secondary) !important;\n}\n.nav-footer a:hover {\n  color: var(--ml-blue) !important;\n}\n\n/* ---- breadcrumb (shared between search and PDP) ------------------------- */\n.andes-breadcrumb__link,\n.andes-breadcrumb__item,\n.ui-search-breadcrumb__title,\n.ui-search-breadcrumb__link {\n  color: var(--ml-text-secondary) !important;\n}\n.andes-breadcrumb__link:hover {\n  color: var(--ml-blue) !important;\n}\n.andes-breadcrumb__chevron {\n  color: var(--ml-text-muted) !important;\n}\n\n/* ===== 20-cards.css ===== */\n/* ============================================================================\n   20-cards.css — every container surface in MELI's design system.\n   `.andes-card` is the primitive: 86–127 instances per page, and the result\n   card `.poly-card` is itself an `.andes-card`. Styling the family covers\n   pages that do not exist yet.\n   ========================================================================== */\n\n/* ---- Andes card family -------------------------------------------------- */\n.andes-card,\n.andes-card--primary,\n.andes-card--flat,\n.andes-card--elevated,\n.andes-card__content,\n.andes-card__header,\n.andes-card__footer,\n.andes-card--padding-0,\n.andes-card--padding-8,\n.andes-card--padding-16,\n.andes-card--padding-24,\n.andes-card__overlap {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n.andes-card {\n  border-color: var(--ml-border-subtle) !important;\n  box-shadow: none !important;\n}\n.andes-card--elevated {\n  box-shadow: var(--ml-shadow-card) !important;\n}\n.andes-card__header--border,\n.andes-card__footer--border {\n  border-color: var(--ml-border-subtle) !important;\n}\n.andes-card__header-title,\n.andes-card__footer--common,\n.andes-card__footer--link {\n  color: var(--ml-text-primary) !important;\n}\n.andes-card__footer-arrow {\n  color: var(--ml-text-muted) !important;\n}\n\n/* Nested containers painted white by MELI inside a card must go transparent,\n   not \"surface-1\", so they blend instead of stacking rectangles. */\n.andes-card__content > div,\n.andes-card__content > section,\n.andes-card__content > ul {\n  background-color: transparent !important;\n}\n\n/* ---- Product card: results grid and lists -------------------------------- */\n.poly-card,\n.poly-card--CORE,\n.poly-card--CPG,\n.poly-card--grid-card,\n.poly-card--list,\n.poly-card--list-card,\n.poly-card--xlarge,\n.poly-card--large,\n.poly-card--medium,\n.poly-card--no-highlight,\n.poly-card--highlight-component,\n.recos-polycard,\n.poly-card__content,\n.poly-card__portada {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n.poly-card {\n  transition: background-color 0.12s ease, box-shadow 0.12s ease;\n}\n.poly-card:hover {\n  background-color: var(--ml-surface-2) !important;\n  box-shadow: var(--ml-shadow-card) !important;\n}\n\n/* Disabled / unavailable listing */\n.poly-card--disabled {\n  background-color: var(--ml-surface-1) !important;\n  opacity: 0.55;\n}\n\n/* Image area: a slightly recessed well so photos read as \"inside\" the card.\n   Photos themselves are only dimmed by --ml-img-dim in base.css. */\n.poly-card__portada {\n  background-color: var(--ml-surface-2) !important;\n}\n.poly-component__image-overlay {\n  background: linear-gradient(\n    to bottom,\n    rgba(6, 8, 11, 0) 55%,\n    rgba(6, 8, 11, 0.35) 100%\n  ) !important;\n}\n\n/* Colour-dot widget on the image corner */\n.poly-variations-compacted__circle {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n\n/* ---- Cart / checkout cards (`cl-*` is a different subsystem) ------------- */\n.cl-grouped-card,\n.cl-grouped-card__content,\n.cl-card-header,\n.cl-card-header__coupon-card {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.cl-image-label {\n  background-color: var(--ml-surface-3) !important;\n}\n/* `cl-image-label__overlay` is NOT a panel: it is the translucent scrim that\n   sits ON TOP of the product photo behind the \"AGOTADO\" / \"QUEDAN N\" badge.\n   It was accidentally included in the opaque panel list above, which painted a\n   112x112 rectangle of --ml-surface-1 over the whole thumbnail of every\n   labelled product. Only those products lost their photo, which is exactly the\n   reported \"en el carrito solo con los que dicen agotado se pierde la imagen\".\n   Measured: overlay box 112x112, background rgb(24,28,34) — my surface-1.\n   A scrim must stay translucent; it exists to darken the photo, never hide it. */\n.cl-image-label__overlay,\n[class*=\"cl-image-label__overlay\"] {\n  background-color: transparent !important;\n  background-image: none !important;\n}\n.cl-grouped-card + .cl-grouped-card {\n  border-top-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Seller hub modules (vendedores.mercadolibre.com.co) ------------------ */\n.module-card,\n.module-card__header,\n.module-card__content,\n.tasks-card__subcard,\n.control-panel__segment,\n.recommendation-card-desktop,\n.filter-recommendation-card,\n.recommendation-card__card,\n.recommendation_transition_card,\n.seller-monitor__loading-card,\n.seller-monitor__loading-list {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n/* The seller hub paints its own canvas rgb(231,233,243). */\n.no-href,\n.andes-layout,\n.main-container,\n.page-container {\n  background-color: transparent !important;\n}\n\n/* ---- Modeless mini-modals / popovers ------------------------------------ */\n.modeless-box,\n.modeless-box-scroll-rail,\n.price-filter__value {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n\n/* ---- Tables and the striped spec table on the PDP ----------------------- */\n.andes-table,\n.andes-table__row,\n.andes-table__column,\n.andes-table__header,\n.andes-table__header__container,\n.ui-vpp-striped-specs,\n.ui-vpp-striped-specs__row,\n.ui-vpp-striped-specs__row__column {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.andes-table__header,\n.andes-table__header--left {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* Striped rows: the light theme alternates #fff / #f5f5f5. */\n.ui-vpp-striped-specs__row:nth-child(odd),\n.andes-table__row:nth-child(even) {\n  background-color: var(--ml-surface-2) !important;\n}\n\n/* ---- Editorial / SEO blocks that MELI injects into listings ------------- */\n.seo-ui-card-blog-entry-container,\n.seo-ui-card-blog-entry,\n.seo-ui-card-blog-entry__content {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Carousels ---------------------------------------------------------- */\n.andes-carousel-snapped__control,\n.andes-carousel-snapped__control--size-small,\n.andes-carousel-snapped__control--size-large {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: var(--ml-shadow-card) !important;\n}\n.andes-carousel-snapped__control:hover:not(.andes-carousel-snapped__control--disabled) {\n  background-color: var(--ml-surface-4) !important;\n}\n.andes-carousel-snapped__control--disabled {\n  opacity: 0.35;\n}\n.ui-search-carousel__item-generic-card {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ===== 30-text.css ===== */\n/* ============================================================================\r\n   30-text.css — text colours, derived from the measured census.\r\n   Every selector below exists because the audit proved it carries a literal\r\n   light-theme colour. IMPORTANT: `.polylabel-fw-*` and `.polylabel-fs-*` are\r\n   font utilities, NOT colour classes — never set colour on them.\r\n   ========================================================================== */\r\n\r\n/* ---- MELI's semantic typography classes --------------------------------- */\r\n.andes-typography {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.andes-typography--color-primary {\r\n  color: var(--ml-text-primary) !important; /* was rgba(0,0,0,.9) */\r\n}\r\n.andes-typography--color-secondary {\r\n  color: var(--ml-text-secondary) !important; /* was rgba(0,0,0,.55) */\r\n}\r\n.andes-typography--color-link,\r\n.andes-typography--color-action {\r\n  color: var(--ml-blue) !important;\r\n}\r\n\r\n/* ---- Generic text utility MELI uses everywhere --------------------------- */\r\n.ui-label-builder {\r\n  color: var(--ml-text-secondary) !important; /* was #666 */\r\n}\r\n\r\n/* ---- Listing: card text -------------------------------------------------- */\r\n.poly-component__title,\r\n.poly-component__title-wrapper a,\r\na.poly-component__title {\r\n  color: var(--ml-text-primary) !important; /* was rgba(0,0,0,.9) */\r\n}\r\n.poly-component__title:hover {\r\n  color: var(--ml-blue) !important;\r\n}\r\n.polylabel-label {\r\n  color: var(--ml-text-primary) !important; /* was rgba(0,0,0,.9) / #737373 */\r\n}\r\n.poly-component__review-compacted .polylabel-label {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.poly-component__seller,\r\n.poly-component__attributes,\r\n.poly-component__cpg {\r\n  color: var(--ml-text-muted) !important;\r\n}\r\n\r\n/* Price: base text is primary; the struck \"previous\" price is muted. */\r\n.poly-price__amount,\r\n.poly-price__current,\r\n.andes-money-amount {\r\n  color: inherit;\r\n}\r\n.andes-money-amount--previous,\r\n.andes-money-amount--previous .andes-money-amount__fraction,\r\n.andes-money-amount--previous .andes-money-amount__currency-symbol {\r\n  color: var(--ml-text-muted) !important;\r\n  text-decoration-color: var(--ml-text-muted) !important;\r\n}\r\n.andes-money-amount__discount,\r\n.poly-price__discount-polylabel {\r\n  color: var(--ml-green) !important;\r\n}\r\n.poly-price__installments,\r\n.poly-price__installments .andes-money-amount,\r\n.andes-money-amount--cents-comma {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* Green semantic text: shipping. Literal #00a650 lives on these containers. */\r\n.poly-shipping-v2__item,\r\n.poly-component__shipping-v2,\r\n.poly-component__shipping,\r\n.ui-search-item__shipping,\r\n.ui-search-item__shipping__item,\r\n.shipping-free,\r\n.andes-money-amount--free {\r\n  color: var(--ml-green) !important;\r\n}\r\n\r\n/* Sponsored label (\"Ad\") */\r\n.poly-component__ads-promotions {\r\n  color: var(--ml-text-muted) !important; /* was rgba(0,0,0,.55) */\r\n}\r\n\r\n/* ---- Listing: filters, breadcrumb, pagination --------------------------- */\r\n.ui-search-filter-dt-title {\r\n  color: var(--ml-text-primary, #e3e8ef) !important; /* was #333 (1.7:1 on dark) */\r\n}\r\n.ui-search-filter-name,\r\n.ui-search-filter-container label,\r\n.ui-search-filter-container .ui-search-filter-name {\r\n  /* Facet links are 13-14px regular: --ml-text-secondary (#a9b3c1) measured\r\n     fine numerically but reads as washed-out grey at that size, reported as\r\n     \"las letras apenas se leen\". --ml-text-facet lifts them ~1.4 stops. */\r\n  color: var(--ml-text-facet, #c2cbdb) !important; /* was #666 */\r\n}\r\n.ui-search-filter-container:hover .ui-search-filter-name {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-search-top-keywords__link,\r\n.ui-search-top-keywords__item {\r\n  color: var(--ml-text-secondary) !important; /* was #333 */\r\n}\r\n.ui-search-search-result__quantity-results,\r\n.ui-search-search-result__title {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.andes-pagination__link,\r\n.andes-pagination__button {\r\n  color: var(--ml-text-secondary) !important; /* was rgba(0,0,0,.55) */\r\n}\r\n.andes-pagination__button--current .andes-pagination__link {\r\n  color: var(--ml-text-on-brand) !important;\r\n}\r\n.ui-search-carousel__item-generic-card__title {\r\n  color: var(--ml-text-primary) !important; /* was #666 */\r\n}\r\n.ui-search-range-filter__separator {\r\n  color: var(--ml-text-muted) !important; /* was #999 */\r\n}\r\n\r\n/* ---- PDP ----------------------------------------------------------------- */\r\n.ui-pdp-title,\r\n.ui-pdp-price__second-line .andes-money-amount__fraction,\r\n.ui-pdp-price__second-line .andes-money-amount__currency-symbol,\r\n.ui-pdp-price__original-value .andes-money-amount,\r\n.ui-pdp-seller__link-trigger,\r\n.ui-pdp-description__content,\r\n.ui-pdp-attachment__title,\r\n.ui-pdp-questions__title {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-pdp-price__subtle,\r\n.ui-pdp-price__disclaimer,\r\n.ui-pdp-seller__label-sold,\r\n.ui-pdp-description__text,\r\n.ui-pdp-attachment__text {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.ui-pdp-price__original-value {\r\n  color: var(--ml-text-muted) !important;\r\n}\r\n.ui-pdp-color-variation-picker__label,\r\n.ui-pdp-variations__title {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.ui-review-capability__rating__average,\r\n.ui-review-capability__rating__label {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-review-comment,\r\n.ui-review-comment-content__title,\r\n.ui-review-comment-content__body {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-review-comment-content__date,\r\n.ui-review-capability__status__text {\r\n  color: var(--ml-text-muted) !important;\r\n}\r\n\r\n/* ---- Editorial / SEO blocks --------------------------------------------- */\r\n.seo-ui-card-blog-entry-title {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.seo-ui-card-blog-entry-description {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* ---- Ads ---------------------------------------------------------------- */\r\n.bads-vertical-product-card__title {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.bads-vertical-product-card__price,\r\n.bads-vertical-product-card__subtitle {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* ---- Trust / benefit marks (indigo on light) ---------------------------- */\r\n.ui-pdp-benefits__item,\r\n.ui-pdp-buybox__label,\r\n.ui-pdp-buybox__label-text,\r\n.ui-vip-section-header__label {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-pdp-benefits__item svg,\r\n.ui-pdp-buybox__label svg {\r\n  color: var(--ml-indigo) !important;\r\n}\r\n\r\n/* ---- Links -------------------------------------------------------------- */\r\na {\r\n  color: inherit;\r\n}\r\na.ui-search-link,\r\n.ui-search-link,\r\na.andes-typography--color-link {\r\n  color: var(--ml-blue) !important;\r\n}\r\na.ui-search-link:hover,\r\n.ui-search-link:hover {\r\n  color: var(--ml-blue-fill) !important;\r\n  text-decoration: underline;\r\n}\r\n\r\n/* ---- Placeholders ------------------------------------------------------- */\r\n::placeholder {\r\n  color: var(--ml-text-disabled) !important;\r\n  opacity: 1;\r\n}\n/* ---- Classless <span> inside andes-typography ---------------------------\n   MELI repeatedly breaks inheritance by wrapping a fragment of a sentence in\n   a <span> with NO class and an explicit `color: rgba(0,0,0,.55)` or `.9`.\n   Because the span has no class, no class-based rule can reach it, and because\n   it sets its own colour it never inherits ours.\n\n   Measured cases: the instalment label (\"48 cuotas\") in the payments-methods\n   dialog, and the unit-price wrapper on listings. The rule below restores\n   inheritance for exactly that shape — an unclassed span that is a descendant\n   of an andes type primitive — and nothing wider. */\n.andes-typography span:not([class]),\n.andes-typography--type-body span:not([class]),\n[class*=\"andes-typography--type-\"] span:not([class]) {\n  color: inherit !important;\n}\n/* Where the fragment is deliberately secondary (dates, captions, counts) the\n   parent keeps its own tone, so inheriting is still correct: the parent is\n   already --ml-text-secondary by the rules above. */\n\n/* Same shape one level up: unclassed spans inside the dialog's body text. */\n.andes-modal span:not([class]),\n.andes-modal-dialog span:not([class]) {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n\n/* ===== 40-forms.css ===== */\n/* ============================================================================\n   40-forms.css — buttons, inputs, checkboxes, switches, steppers, badges,\n   dropdowns, tooltips, modals, snackbars. Everything that has a native or\n   design-system control affordance.\n   ========================================================================== */\n\n/* ---- Buttons ------------------------------------------------------------ */\n.andes-button {\n  background-color: transparent !important;\n  border: 1px solid transparent !important;\n  color: var(--ml-text-primary) !important;\n  transition: background-color 0.12s ease, border-color 0.12s ease, color 0.12s ease;\n}\n\n/* Primary / loud: brand blue fill stays, text is off-white. */\n.andes-button--loud,\n.andes-button--primary {\n  background-color: var(--ml-blue-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n.andes-button--loud:hover,\n.andes-button--primary:hover {\n  background-color: #4a90fb !important;\n}\n.andes-button--loud:disabled,\n.andes-button--loud[disabled] {\n  background-color: var(--ml-border-strong) !important;\n  color: var(--ml-text-muted) !important;\n}\n\n/* Secondary / mute: a real dark surface, never white. */\n.andes-button--mute {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n.andes-button--mute:hover {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n\n/* Quiet: tinted blue, blue text — the \"Agregar al carrito\" look. */\n.andes-button--quiet,\n.andes-button--secondary {\n  background-color: var(--ml-blue-tint) !important;\n  border-color: transparent !important;\n  color: var(--ml-blue) !important;\n}\n.andes-button--quiet:hover,\n.andes-button--secondary:hover {\n  background-color: var(--ml-blue-tint-strong) !important;\n}\n\n/* Link-style */\n.andes-button--link,\n.andes-button--text {\n  background-color: transparent !important;\n  color: var(--ml-blue) !important;\n}\n.andes-button--link:hover,\n.andes-button--text:hover {\n  color: var(--ml-blue-fill) !important;\n  text-decoration: underline;\n}\n\n/* Legacy MELI button classes still in the wild */\n.button-primary,\n.btn-primary {\n  background-color: var(--ml-blue-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n.button-secondary,\n.btn-secondary {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Text inputs / selects ---------------------------------------------- */\n.andes-form-control,\n.andes-form-control__control,\n.andes-form-control__field,\n.andes-form-control--textfield input,\n.andes-form-control--textfield select,\n.andes-form-control--textfield textarea,\ninput[type=\"text\"],\ninput[type=\"search\"],\ninput[type=\"email\"],\ninput[type=\"password\"],\ninput[type=\"number\"],\ninput[type=\"tel\"],\ntextarea,\nselect {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: none !important;\n}\n.andes-form-control__field:focus,\ninput:focus,\ntextarea:focus,\nselect:focus {\n  border-color: var(--ml-blue) !important;\n  box-shadow: 0 0 0 1px var(--ml-blue) !important;\n}\n.andes-form-control__label,\n.andes-form-control__helper,\n.andes-form-control__message {\n  color: var(--ml-text-secondary) !important;\n}\n.andes-form-control--error .andes-form-control__control,\n.andes-form-control__control--error {\n  border-color: var(--ml-red) !important;\n}\n.andes-form-control__message--error {\n  color: var(--ml-red) !important;\n}\nselect option {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Checkbox ----------------------------------------------------------- */\n.andes-checkbox__checkbox {\n  background-color: transparent !important;\n  border-color: var(--ml-border-strong) !important;\n}\n.andes-checkbox__icon {\n  color: var(--ml-text-on-brand) !important;\n}\n.andes-checkbox__input:checked + .andes-checkbox__checkbox,\n.andes-checkbox__input:checked ~ .andes-checkbox__checkbox {\n  background-color: var(--ml-blue-fill) !important;\n  border-color: var(--ml-blue-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n.andes-checkbox__label,\n.andes-checkbox--label-right .andes-checkbox__label {\n  color: var(--ml-text-primary) !important;\n}\n.andes-checkbox--disabled {\n  opacity: 0.5;\n}\n\n/* ---- Radio -------------------------------------------------------------- */\n.andes-radio__radio {\n  border-color: var(--ml-border-strong) !important;\n  background-color: transparent !important;\n}\n.andes-radio__input:checked + .andes-radio__radio {\n  border-color: var(--ml-blue) !important;\n  color: var(--ml-blue) !important;\n}\n.andes-radio__label {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Switch (quick filters) --------------------------------------------- */\n.andes-switch__input + .andes-switch__track,\n.andes-switch__track {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n.andes-switch__input:checked + .andes-switch__track,\n.andes-switch__input:checked ~ .andes-switch__track {\n  background-color: var(--ml-blue-fill) !important;\n  border-color: var(--ml-blue-fill) !important;\n}\n.andes-switch__input + .andes-switch__track::after,\n.andes-switch__track::after {\n  background-color: var(--ml-text-primary) !important;\n}\n.andes-switch__label {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Quantity stepper (cart) -------------------------------------------- */\n.andes-input-stepper,\n.andes-input-stepper__container,\n.andes-input-stepper__wrapper,\n.andes-input-stepper__content {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n.andes-input-stepper__button {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-input-stepper__button:hover:not([disabled]) {\n  background-color: var(--ml-surface-3) !important;\n}\n.andes-input-stepper__button[disabled] {\n  color: var(--ml-text-disabled) !important;\n}\n.andes-input-stepper__value {\n  color: var(--ml-text-primary) !important;\n}\n.andes-input-stepper__helper {\n  color: var(--ml-text-muted) !important;\n}\n\n/* ---- Badges ------------------------------------------------------------- */\n.andes-badge {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n}\n.andes-badge--accent {\n  background-color: var(--ml-blue-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n.andes-badge--accent--quiet {\n  background-color: var(--ml-blue-tint) !important;\n  color: var(--ml-blue) !important;\n}\n.andes-badge--gray {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n}\n.andes-badge--gray--quiet {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-secondary) !important;\n}\n.andes-badge--success {\n  background-color: var(--ml-green-tint) !important;\n  color: var(--ml-green) !important;\n}\n.andes-badge--warning {\n  background-color: var(--ml-peach-tint) !important;\n  color: var(--ml-orange) !important;\n}\n.andes-badge--danger,\n.andes-badge--error {\n  background-color: var(--ml-red-tint) !important;\n  color: var(--ml-red) !important;\n}\n.andes-badge__content {\n  color: inherit !important;\n}\n\n/* MELI \"polylabel\" pills: green shipping pill and its variants. */\n.polylabel-pill {\n  background-color: var(--ml-green-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n.polylabel-pill--quiet {\n  background-color: var(--ml-green-tint) !important;\n  color: var(--ml-green) !important;\n}\n\n/* ---- Dropdown / listbox ------------------------------------------------- */\n.andes-dropdown,\n.andes-dropdown__popover,\n.andes-dropdown__menu,\n.andes-list,\n.andes-list__item {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n.andes-list__item:hover,\n.andes-list__item--selected {\n  background-color: var(--ml-surface-4) !important;\n}\n.andes-dropdown__trigger,\n.andes-dropdown__display-values {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Pagination --------------------------------------------------------- */\n.andes-pagination__button {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-pagination__button:hover {\n  background-color: var(--ml-surface-3) !important;\n}\n.andes-pagination__button--current {\n  background-color: var(--ml-blue-fill) !important;\n  border-color: var(--ml-blue-fill) !important;\n}\n.andes-pagination__dot {\n  background-color: var(--ml-text-muted) !important;\n}\n.andes-pagination__arrow-title {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Tooltip / snackbar / modal ----------------------------------------- */\n.andes-tooltip__content,\n.andes-tooltip {\n  background-color: var(--ml-surface-4) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n.andes-snackbar,\n.andes-snackbar__content,\n.andes-toast {\n  background-color: var(--ml-surface-4) !important;\n  color: var(--ml-text-primary) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n.andes-modal__mask,\n.andes-modal-background,\n.andes-overlay {\n  background-color: var(--ml-overlay) !important;\n}\n.andes-modal__container,\n.andes-modal__body,\n.andes-modal__header,\n.andes-modal__footer,\n.andes-dialog,\n.andes-dialog__container {\n  background-color: var(--ml-surface-4) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-modal__close,\n.andes-dialog__close {\n  color: var(--ml-text-secondary) !important;\n}\n/* ---- Modal: single-dash variant ----------------------------------------\n   MELI ships the same dialog under two naming schemes. The rules above use the\n   BEM form (`.andes-modal__container`), but real overlays — the address picker\n   is the measured case — use `.andes-modal-dialog` / `.andes-modal--loose`\n   with no double underscore at all. That variant stayed pure white and was\n   reported as \"el modal de cambiar dirección sale todo blanco\". */\n.andes-modal-dialog,\n.andes-modal--loose,\n.andes-modal-content,\n.modal-dialog,\n.modal-content {\n  background-color: var(--ml-surface-4, #2e3540) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border, #2f3742) !important;\n}\n.andes-modal-dialog :is(h1, h2, h3, h4, h5, p, span, label, li, strong),\n.andes-modal--loose :is(h1, h2, h3, h4, h5, p, span, label, li, strong) {\n  color: inherit !important;\n}\n.andes-modal-dialog a,\n.andes-modal--loose a {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n/* Sticky footer of the dialog: a white bar under a dark panel. */\n.andes-modal-dialog [class*=\"footer\"],\n.andes-modal--loose [class*=\"footer\"],\n.andes-modal-dialog footer,\n.andes-modal--loose footer {\n  background-color: var(--ml-surface-4, #2e3540) !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n/* Backdrop stays a scrim, never a solid. */\n.andes-modal-bg {\n  background-color: var(--ml-overlay, rgba(6, 8, 11, 0.72)) !important;\n}\n\n/* ---- Modal: the bare `.andes-modal` root ---------------------------------\n   Measured on the \"Medios de pago\" overlay (#show-modal), the largest dialog\n   MELI builds. Its root is `<div class=\"andes-modal modal andes-modal--large\">`\n   — no `__container`, no `-dialog`, just `.andes-modal`. Every modal rule in\n   this file keyed off a longer name, so this root kept its default white and\n   the dialog rendered as a white sheet with a dark header sitting on top of\n   it: the reported \"panel blanco con el contenido oscuro\".\n\n   `.andes-modal-bg` / `.andes-modal__overlay` are the two scrims MELI uses;\n   both must stay a translucent dark scrim, never a solid surface. */\n.andes-modal,\n.andes-modal--large,\n.andes-modal--medium,\n.andes-modal--small,\n.andes-modal--full {\n  background-color: var(--ml-surface-4, #2e3540) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border, #2f3742) !important;\n}\n.andes-modal__overlay,\n.andes-modal__mask--dark,\n.andes-modal-bg {\n  background-color: var(--ml-overlay, rgba(6, 8, 11, 0.78)) !important;\n}\n/* Children inherit from the root so nothing inside can re-assert #333 or\n   rgba(0,0,0,.9) on its own; the exceptions below re-tint deliberately. */\n.andes-modal :is(h1, h2, h3, h4, h5, h6, p, span, div, li, dt, dd, strong, em) {\n  color: inherit !important;\n}\n.andes-modal a,\n.andes-modal a * {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n/* Sticky header/footer bars inside the large dialog. */\n.andes-modal__header,\n.andes-modal__footer,\n.andes-modal [class*=\"modal__header\"],\n.andes-modal [class*=\"modal__footer\"] {\n  background-color: var(--ml-surface-4, #2e3540) !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n/* Media slots: the payment-method cards draw white logos on white tiles. Keep\n   the tile a raised surface, never pure white, and never dim the logo. */\n.andes-modal img,\n.andes-modal [class*=\"thumbnail\"],\n.andes-modal [class*=\"logo\"] {\n  background-color: var(--ml-surface-2, #1f242c) !important;\n}\n\n/* ===== 50-coverage.css ===== */\n/* ============================================================================\n   50-coverage.css — everything discovered by RE-AUDITING the page with the\n   theme already applied. Each block here corresponds to a measured leftover\n   (white surface or dark text) on `listado.mercadolibre.com.co/suplementos`.\n   ========================================================================== */\n\n/* ---- Switch -------------------------------------------------------------\n   MELI draws the track on input::before (rgba(0,0,0,.1)) and the knob on\n   input::after (#fff). There is no `.andes-switch__track` element. */\n.andes-switch__input::before {\n  background-color: var(--ml-border-strong) !important;\n}\n.andes-switch__input:checked::before {\n  background-color: var(--ml-blue-fill) !important;\n}\n.andes-switch__input::after {\n  background-color: var(--ml-text-primary) !important;\n  box-shadow: none !important;\n}\n.andes-switch__input:disabled::before {\n  opacity: 0.45;\n}\n.andes-switch__label,\n.ui-search-filter-highlighted__title {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Money amounts ------------------------------------------------------\n   `.andes-money-amount__fraction` carries its own rgba(0,0,0,.9); `inherit`\n   alone loses the cascade battle, so force it to follow the parent. */\n.andes-money-amount__currency-symbol,\n.andes-money-amount__fraction,\n.andes-money-amount__currency {\n  color: inherit !important;\n}\n.poly-price__current,\n.poly-price__amount,\n.poly-price__amount .andes-money-amount__fraction {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Remaining white surfaces (measured after first pass) --------------- */\n.bads-vertical-product-card__image-container {\n  background-color: var(--ml-surface-2) !important;\n}\n.ui-search-filter-highlighted__container {\n  background-color: var(--ml-surface-2) !important;\n  border: 1px solid var(--ml-border-subtle) !important;\n}\n.ui-search-filter-highlighted__container:hover {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n}\n.nav-assistant,\n.nav-assistant__trigger,\n.nav-assistant__container {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-message,\n.andes-message--informative,\n.andes-message--loud,\n.andes-message__content,\n.ui-search-andes-message__card,\n.ui-search-message-content {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n.ui-search-bottom-ads__wrapper,\n.ui-search-footer-components {\n  background-color: transparent !important;\n}\n.ui-search-carousel__item-generic-main,\n.ui-search-carousel__item-generic__view-more {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-blue) !important;\n}\n.bads-adaptive-carousel__arrow {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-pagination__link {\n  background-color: transparent !important;\n}\n\n/* ---- Category mega-menu panel ------------------------------------------\n   MELI ships this panel as solid #333 with white links. Keep it dark, but on\n   our own surface so it matches the rest of the header. */\n.nav-categs-departments,\n.nav-categs-departments__list {\n  background-color: var(--ml-surface-3) !important;\n}\n.nav-categs-departments a,\n.nav-categs-departments__list a,\n.nav-categs-departments__list--static a,\n.nav-categs-departments__list--dynamic a {\n  color: var(--ml-text-primary) !important;\n}\n.nav-categs-departments a:hover {\n  color: var(--ml-blue) !important;\n}\n\n/* ---- Footer leftovers --------------------------------------------------- */\n.nav-footer-access-title,\n.nav-footer-secondaryinfo,\n.nav-footer-copyright,\n.nav-footer-access-list,\n.nav-footer-access-banner {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Header account switcher ------------------------------------------- */\n.nav-account-switcher__title,\n.nav-account-switcher__add-account-text {\n  color: var(--ml-text-primary) !important;\n}\n.nav-account-switcher__subtitle {\n  color: var(--ml-text-secondary) !important;\n}\n.nav-account-switcher__avatar,\n.nav-account-switcher__avatar-item {\n  background-color: var(--ml-surface-2) !important;\n}\n.nav-account-switcher__avatar-initials,\n.nav-header-profile-evolution__user-initials {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Scattered #333 headings ------------------------------------------- */\n.ui-search-money-picker-desktop-dt-title,\n.ui-search-view-options__title,\n.modeless-box-header {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Coupon pill -------------------------------------------------------- */\n.poly-coupons__pill {\n  background-color: var(--ml-blue-tint) !important;\n  color: var(--ml-blue) !important;\n}\n\n/* ---- Border normalisation ----------------------------------------------\n   MELI mixes #ededed, #d5d9d9, #eee, #efefef and rgb(213,217,217) for the\n   same job. On dark, all of them are invisible walls of light grey. */\n.andes-card,\n.andes-card__header--border,\n.andes-card__footer--border,\n.andes-table,\n.andes-table__row,\n.ui-search-filter-dl,\n.poly-card,\n.cl-grouped-card,\n.module-card,\n.andes-carousel-snapped__container {\n  border-color: var(--ml-border-subtle) !important;\n}\n.andes-form-control__control,\n.andes-form-control__field,\n.andes-input-stepper,\n.andes-checkbox__checkbox,\n.andes-radio__radio,\n.andes-button--mute {\n  border-color: var(--ml-border) !important;\n}\nhr,\n.andes-divider {\n  border-color: var(--ml-border-subtle) !important;\n}\n/* ---- Andes thumbnail stack ---------------------------------------------\n   `andes-thumbnail` is used for image stacks plus a \"+N\" remainder badge.\n   The badge text is a bare <span> that the light theme paints dark; on our\n   dark overlay it disappears entirely.\n\n   NOTE: the letterbox colour is deliberately NOT set here. A thumbnail box is\n   a letterbox sized to the product photo's aspect, and its leftover band must\n   stay light or the photo reads as a dark hole. It is owned by\n   --ml-thumb-plate in 98-late-fixes.css, which states the reasoning once. */\n.andes-thumbnail,\n.andes-thumbnail-container,\n[class*=\"andes-thumbnail\"] {\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-thumbnail span,\n.andes-thumbnail-container span,\n[class*=\"andes-thumbnail\"] > span {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- SEO \"trending searches\" list --------------------------------------\n   Every listing ends with ~70 keyword links under `.seo-ui-trends-entry-*`.\n   Each keyword ships its own dark colour, hence the ×69 dark-text count. */\n[class*=\"seo-ui-trends\"],\n[class*=\"seo-ui-trends-entry\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n}\n[class*=\"seo-ui-trends-entry-keyword\"],\n[class*=\"seo-ui-trends\"] a,\n[class*=\"seo-ui-trends\"] span {\n  color: var(--ml-text-secondary) !important;\n}\n[class*=\"seo-ui-trends\"] a:hover,\n[class*=\"seo-ui-trends-entry-keyword\"]:hover {\n  color: var(--ml-blue) !important;\n}\n[class*=\"seo-ui-trends\"] [class*=\"__title\"],\n[class*=\"seo-ui-trends\"] h2,\n[class*=\"seo-ui-trends\"] h3 {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Category nav strip ------------------------------------------------\n   `nav-category--multi` is the wider variant of the horizontal department\n   bar under the header; the plain `.nav-category` rule did not reach it. */\n.nav-category,\n[class*=\"nav-category\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-secondary) !important;\n}\n[class*=\"nav-category\"] a,\n[class*=\"nav-category\"] span,\n[class*=\"nav-category\"] li {\n  color: var(--ml-text-secondary) !important;\n}\n[class*=\"nav-category\"] a:hover {\n  color: var(--ml-blue) !important;\n}\n\n/* ---- Andes tabs --------------------------------------------------------\n   `.andes-tab__link` carries rgba(0,0,0,.9) and a bare <span> title inside it.\n   Tabs appear in the seller hub, account settings, PDP and help pages, so the\n   fix belongs on the design-system primitive, not per page. */\n.andes-tabs,\n.andes-tabs__container,\n[class*=\"andes-tabs__container\"] {\n  background-color: transparent !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-tab__link,\n[class*=\"andes-tab__link\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n  border-color: transparent !important;\n}\n.andes-tab__link span,\n[class*=\"andes-tab__link\"] span,\n[class*=\"andes-tab-wrapper__title\"] {\n  color: inherit !important;\n}\n.andes-tab__link:hover,\n[class*=\"andes-tab__link\"]:hover {\n  color: var(--ml-text-primary) !important;\n}\n.andes-tab__link[aria-selected=\"true\"],\n.andes-tab__link--active,\n[class*=\"andes-tab__link--active\"],\n[class*=\"andes-tab__link\"][aria-selected=\"true\"] {\n  color: var(--ml-blue) !important;\n  border-color: var(--ml-blue) !important;\n}\n\n/* ---- Andes carousel edge fades -----------------------------------------\n   MELI blends a carousel into the page by painting PSEUDO-ELEMENTS at its\n   edges with `linear-gradient(to right, rgb(245,245,245), transparent)` and\n   solid `rgb(245,245,245)`. Those are invisible to every audit that reads\n   `background-color` of real elements, and to `elementFromPoint` (pseudo\n   elements are not hit-testable) — but on dark they render as BRIGHT WHITE\n   WEDGES over the page. This was the pair of white blocks flanking the seller\n   hub content.\n\n   Replacing them with the page tone keeps the exact same visual effect MELI\n   intended (a soft fade into the background) in the dark theme. */\n[class*=\"andes-carousel\"]::before,\n[class*=\"andes-carousel-snapped\"]::before,\n[class*=\"andes-carousel-snapped__controls-wrapper\"]::before {\n  background-image: linear-gradient(\n    to right,\n    var(--ml-surface-0) 0%,\n    transparent 100%\n  ) !important;\n  background-color: transparent !important;\n}\n[class*=\"andes-carousel\"]::after,\n[class*=\"andes-carousel-snapped\"]::after,\n[class*=\"andes-carousel-snapped__controls-wrapper\"]::after {\n  background-image: linear-gradient(\n    to left,\n    var(--ml-surface-0) 0%,\n    transparent 100%\n  ) !important;\n  background-color: transparent !important;\n}\n/* The partially visible last slide is masked with a SOLID light overlay. */\n[class*=\"andes-carousel-snapped__slide\"]::after {\n  background-color: var(--ml-surface-0) !important;\n  background-image: none !important;\n}\n\n/* ---- Pagination: the \"current page\" chip ---------------------------------\n   `.andes-pagination__link` itself is transparent, but its wrapper\n   `.andes-pagination__button` carries the white chip in some themes, which the\n   probe flagged as a light surface on my-reviews. Neutralise both; the active\n   page keeps the brand fill. */\n.andes-pagination__button,\n.andes-pagination__link {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-secondary) !important;\n}\n.andes-pagination__button:hover,\n.andes-pagination__link:hover {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n}\n.andes-pagination__button--current,\n.andes-pagination__button--current .andes-pagination__link,\n.andes-pagination__link[aria-current=\"page\"] {\n  background-color: var(--ml-blue-fill, #3483fa) !important;\n  border-color: transparent !important;\n  color: var(--ml-text-on-brand, #f2f5f8) !important;\n}\n\n/* ---- Pagination on paged lists: MELI wins by specificity ----------------\n   `.ui-list-paged--content .andes-pagination .andes-pagination__link\n   [aria-current=\"page\"]` sets `background-color: #fff !important` — three\n   classes plus an attribute, so the generic pagination rules above lose and\n   the active page number stayed a white chip on dark (flagged on my-reviews).\n\n   Matching the same compound and appending our colour restores the brand\n   fill. Written as one selector so it beats the original on source order with\n   equal specificity. */\n.ui-list-paged--content .andes-pagination .andes-pagination__link[aria-current=\"page\"],\n.ui-list-paged--content .andes-pagination .andes-pagination__link[aria-current=\"page\"]:hover,\n[class*=\"list-paged\"] .andes-pagination__link[aria-current=\"page\"] {\n  background-color: var(--ml-blue-fill, #3483fa) !important;\n  border-color: transparent !important;\n  color: var(--ml-text-on-brand, #f2f5f8) !important;\n}\n\n/* The active page chip still resolved to white after the rule above: the\n   winning declaration lives in a rule whose specificity I could not isolate\n   from the page (its sheet is not enumerable from the document). Verified\n   empirically that adding the parent button to the chain wins, so the compound\n   is kept explicit rather than guessed. */\n.andes-pagination__button--current .andes-pagination__link,\n.andes-pagination__button--current .andes-pagination__link[aria-current=\"page\"],\n.andes-pagination .andes-pagination__button--current .andes-pagination__link {\n  background-color: var(--ml-blue-fill, #3483fa) !important;\n  color: var(--ml-text-on-brand, #f2f5f8) !important;\n}\n\n/* The active page chip kept resolving to white even with an `!important`\n   background-color at matching specificity, while `color` from the very same\n   rule DID apply — so a more specific `!important` background-color wins and\n   is not visible from the document's enumerable sheets.\n\n   Fixing it by out-specifying an unknown competitor is a guessing game. Painting\n   with `background-image` instead is deterministic: MELI sets only\n   `background-color` on this element, so a gradient layer is uncontested and it\n   renders on top of whatever white fill remains underneath. `color` already\n   lands from the rule above, so the label stays legible. */\n.andes-pagination__button--current .andes-pagination__link,\n.andes-pagination .andes-pagination__button--current .andes-pagination__link,\n.andes-pagination__link[aria-current=\"page\"] {\n  background-image: linear-gradient(\n    var(--ml-blue-fill, #3483fa),\n    var(--ml-blue-fill, #3483fa)\n  ) !important;\n  color: var(--ml-text-on-brand, #f2f5f8) !important;\n}\n\n/* ===== 60-search.css ===== */\n/* ============================================================================\n   60-search.css — results listing (listado.mercadolibre.com.co paths), its\n   chrome (sort bar, breadcrumb, pagination) and the whole filter sidebar.\n\n   Selectors come from the measured map in NOTAS-mercadolibre-dark.md §7.1\n   (result card anatomy) and §7.4 (filter sidebar). Nothing here is guessed.\n   Families whose suffix MELI renames between deploys (`ui-search-sort*`,\n   `ui-search-carousel*`, `ui-search-applied-filters*`) are matched on the\n   class *family* through [class^=]/[class*=] instead of a fixed descendant\n   chain, which is what keeps this file alive across MELI updates (S4).\n\n   Already dark elsewhere — intentionally not repeated here:\n     card surface, hover .......... 20-cards.css   (.poly-card, .andes-card)\n     `.ui-search-carousel__item-generic-card`\n       surface .................... 20-cards.css\n     `.ui-search-carousel__item-generic-main`,\n       `__view-more` ............... 50-coverage.css\n     `.ui-search-carousel__item-generic-card__title`\n       ............................ 30-text.css\n     prices / shipping / labels ... 30-text.css\n     filter name + group title .... 30-text.css\n     quick-filter title ........... 50-coverage.css\n     money-picker + view-options\n       titles ..................... 50-coverage.css\n     message cards, bottom ads .... 50-coverage.css\n     dropdown / switch / inputs ... 40-forms.css\n     breadcrumb + pagination text . 10-header.css / 30-text.css\n   ========================================================================== */\n\n/* ---- Listing shell ------------------------------------------------------\n   Page, layout column and results container are #f5f5f5 / #fff in the light\n   theme. They have to dissolve into the page, not stack rectangles. */\n.ui-search-main,\n.ui-search-layout,\n.ui-search-results,\n.ui-search-results--without-disclaimer {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Filter sidebar -----------------------------------------------------\n   aside > section.ui-search-filter-groups > div.ui-search-filter-dl >\n   ul > li.ui-search-filter-container (measured, §7.4). */\naside.ui-search-sidebar,\nsection.ui-search-filter-groups {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.ui-search-filter-dl {\n  background-color: transparent !important;\n  border-bottom: 1px solid var(--ml-border-subtle) !important;\n}\n.ui-search-filter-dt-title {\n  border-color: var(--ml-border-subtle) !important;\n}\n.ui-search-filter-container {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.ui-search-filter-container:hover {\n  background-color: var(--ml-surface-2) !important;\n}\n/* A checked filter option: the light theme marks it with the blue tint and a\n   blue name. `.ui-search-filter-name`'s *base* colours are in 30-text.css; this\n   is only the selected state, which that file does not cover. */\n.ui-search-filter-container--selected,\n.ui-search-filter-container[aria-checked=\"true\"],\n.ui-search-filter-container:has(.andes-checkbox__input:checked) {\n  background-color: var(--ml-blue-tint) !important;\n}\n.ui-search-filter-container--selected .ui-search-filter-name,\n.ui-search-filter-container[aria-checked=\"true\"] .ui-search-filter-name,\n.ui-search-filter-container:has(.andes-checkbox__input:checked) .ui-search-filter-name {\n  color: var(--ml-text-primary) !important;\n}\n\n/* Quick filters (\"Envío gratis\", \"Ahora 12\"…): pill rows above the tree. */\n.ui-search-filter-highlighted {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border: 1px solid var(--ml-border-subtle) !important;\n}\n.ui-search-filter-highlighted:hover {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n}\n.ui-search-filter-highlighted__title {\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* Price picker rows (money picker) and the colour swatch strip. */\n.ui-search-money-picker-desktop__li {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.ui-search-money-picker-desktop-dt-title {\n  border-color: var(--ml-border-subtle) !important;\n}\n/* \"$\" … \"a\" … \"$\" separator between the two price inputs. Its grey is set in\n   30-text.css; on dark it also draws a #d5d9d9 rule that has to go. */\n.ui-search-range-filter__separator {\n  border-color: var(--ml-border-subtle) !important;\n  background-color: transparent !important;\n}\n.ui-search-filter-colors {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* Grid / list switcher: two icon buttons that MELI paints #fff. */\n.ui-search-view-options__item {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n  border: 1px solid transparent !important;\n}\n.ui-search-view-options__item:hover {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n}\n.ui-search-view-options__item--selected,\n.ui-search-view-options__item[aria-pressed=\"true\"],\n.ui-search-view-options__item[class*=\"--active\"] {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n\n/* ---- Applied filter chips (\"Limpiar filtros\" row) ----------------------- */\n.ui-search-applied-filters {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.ui-search-applied-filters__pill {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border: 1px solid var(--ml-border) !important;\n}\n.ui-search-applied-filters__pill:hover {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n\n/* ---- Sort bar -----------------------------------------------------------\n   \"Ordenar por\" is #666 next to an andes dropdown; the dropdown panel,\n   trigger and items are already dark from 40-forms.css. Only the bar's own\n   label text needs work, so this block stays deliberately small. */\n.ui-search-sort,\n[class^=\"ui-search-sort\"],\n[class*=\" ui-search-sort\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n[class^=\"ui-search-sort\"] label,\n[class*=\" ui-search-sort\"] label,\n[class^=\"ui-search-sort\"] .andes-dropdown__display-values,\n[class*=\" ui-search-sort\"] .andes-dropdown__display-values {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Carousels (\"Ofertas\", sponsored rows, related searches) ------------\n   Only the rail root is reset here, on purpose: the generic-card surface,\n   its title and its \"ver más\" tile are already dark in 20-cards.css /\n   50-coverage.css / 30-text.css, so a blanket `[class*=\"ui-search-carousel\"]`\n   reset in this later file would win on equal specificity and strip them. */\n.ui-search-carousel {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.ui-search-carousel > h2,\n.ui-search-carousel > header h2,\n.ui-search-carousel > header h3 {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- \"Búsquedas relacionadas\" pills ------------------------------------- */\n.ui-search-top-keywords__item {\n  background-color: var(--ml-surface-2) !important;\n  border: 1px solid var(--ml-border) !important;\n}\n.ui-search-top-keywords__item:hover {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n.ui-search-top-keywords__item:hover .ui-search-top-keywords__link {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Breadcrumb ---------------------------------------------------------\n   Link/item/chevron colours live in 10-header.css (shared with the PDP);\n   only the strip itself needs to stop being white. */\n.ui-search-breadcrumb,\n.andes-breadcrumb {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Result count line (\"1.234 resultados\") -----------------------------\n   Colour is secondary from 30-text.css; this only removes the divider MELI\n   paints below it in #ededed. */\n.ui-search-search-result__quantity-results {\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Pagination ---------------------------------------------------------\n   Buttons, current page, dots and arrows are already dark from 40-forms.css\n   and 30-text.css. What is left is the disabled/edge state, where MELI keeps\n   a white button with #999 text. Mapping: disabled drops to the recessed\n   --ml-surface-1 and keeps --ml-text-muted, which still clears 4.5:1 (4.68:1)\n   on that surface — the muted token on the normal --ml-surface-2 button would\n   only reach 4.27:1 and fail. */\n.andes-pagination {\n  border-color: var(--ml-border-subtle) !important;\n}\n.andes-pagination__button--disabled,\n.andes-pagination__button[disabled] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.andes-pagination__button--disabled .andes-pagination__link,\n.andes-pagination__button[disabled] .andes-pagination__link {\n  color: var(--ml-text-muted) !important;\n}\n\n/* ---- Message cards / bottom ads ----------------------------------------\n   `.ui-search-message-content`, `.ui-search-andes-message__card` and\n   `.ui-search-bottom-ads__wrapper` are already handled in 50-coverage.css —\n   not repeated here on purpose. */\n/* ---- Filter sidebar: structural safety net -----------------------------\n   MELI ships at least two different markups for this column depending on the\n   A/B bucket, and the class-based rules above only cover the bucket I could\n   measure. In a real-user session the group titles (\"Tipo de promoción\",\n   \"Categorías\") and the facet list still rendered as `#333` / `#666` on the\n   dark page — 1.7:1 and 3.2:1, i.e. effectively unreadable.\n\n   These rules do NOT depend on MELI's class names: they anchor on the sidebar\n   container and reach its headings and links structurally, with literal\n   fallbacks so the colour is correct even if a token fails to resolve. */\naside,\n[class*=\"ui-search-sidebar\"],\n[class*=\"ui-search-filter-groups\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n/* Group titles and any heading inside the facet column. */\naside h2,\naside h3,\naside h4,\naside dt,\n[class*=\"ui-search-sidebar\"] h2,\n[class*=\"ui-search-sidebar\"] h3,\n[class*=\"ui-search-sidebar\"] h4,\n[class*=\"ui-search-filter\"] h2,\n[class*=\"ui-search-filter\"] h3,\n[class*=\"ui-search-filter\"] h4,\n[class*=\"filter-dt-title\"],\n[class*=\"filter-title\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n/* Facet entries: label + count, whatever the wrapper class is. */\naside li,\naside li a,\naside li label,\naside li span,\n[class*=\"ui-search-filter\"] li,\n[class*=\"ui-search-filter\"] li a,\n[class*=\"ui-search-filter\"] li label,\n[class*=\"ui-search-filter\"] li span,\n[class*=\"filter-name\"] {\n  color: var(--ml-text-facet, #c2cbdb) !important;\n}\n/* Keep the interaction feedback: hover and the applied facet go bright/blue. */\naside li:hover,\naside li a:hover,\n[class*=\"ui-search-filter\"] li:hover,\n[class*=\"ui-search-filter\"] li:hover a,\n[class*=\"ui-search-filter\"] li:hover span {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\naside li[class*=\"selected\"],\naside li[class*=\"active\"],\n[class*=\"ui-search-filter\"] li[class*=\"--selected\"],\n[class*=\"ui-search-filter\"] li[class*=\"active\"] {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n/* Result count / \"N productos\" line, which sits in the same column. */\n[class*=\"result-count\"],\n[class*=\"ui-search-title\"],\n[class*=\"ui-search-results-count\"] {\n  color: var(--ml-text-facet, #c2cbdb) !important;\n}\n\n/* ===== 70-pdp.css ===== */\n/* ============================================================================\r\n   70-pdp.css — product detail page (www.mercadolibre.com.co/.../p/MCO*).\r\n\r\n   Measured namespaces on the PDP (§7.2): ui-pdp 804, ui-review 348,\r\n   ui-vpp 284, ui-recommendations 45, ui-video 42, ui-seller 39, ui-box 5,\r\n   ui-vip 1. Families whose leaf names change between deploys are matched by\r\n   class family ([class^=]/[class*=]) so a renamed leaf cannot unstyle a block.\r\n\r\n   Rules followed here:\r\n   • Product photos are NEVER filtered, dimmed or recoloured in this file.\r\n     Photo brightness is owned by --ml-img-dim in base.css.\r\n   • Brand identity is kept: blue fills for primary actions (40-forms.css),\r\n     green for savings / free shipping, yellow only for brand marks.\r\n   • High-specificity + !important because MELI ships inline styles here.\r\n\r\n   Already dark elsewhere — intentionally not repeated here:\r\n     cards / carousels / specs stripes .. 20-cards.css\r\n     andes-table* surfaces + stripes .... 20-cards.css\r\n     title, price, description, review\r\n       and Q&A text ..................... 30-text.css\r\n     andes-button*, badges, steppers ... 40-forms.css\r\n     recos-polycard surface ............ 20-cards.css\r\n   ========================================================================== */\r\n\r\n/* ---- Gallery -----------------------------------------------------------\r\n   MELI ships white figures. They become a recessed well so the photo still\r\n   reads as an object on a dark surface. No filter: see base.css. */\r\n.ui-pdp-gallery,\r\n.ui-pdp-gallery__figure {\r\n  background-color: var(--ml-surface-1) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n.ui-pdp-gallery__figure {\r\n  border: 1px solid var(--ml-border-subtle) !important;\r\n}\r\n.ui-pdp-gallery__thumbnail {\r\n  background-color: var(--ml-surface-2) !important;\r\n  border: 1px solid var(--ml-border) !important;\r\n}\r\n.ui-pdp-gallery__thumbnail:hover {\r\n  border-color: var(--ml-border-strong) !important;\r\n}\r\n.ui-pdp-gallery__thumbnail--selected,\r\n.ui-pdp-gallery__thumbnail[aria-current=\"true\"],\r\n.ui-pdp-gallery__thumbnail[class*=\"--active\"] {\r\n  border-color: var(--ml-blue) !important;\r\n}\r\n.ui-pdp-gallery__zoom {\r\n  background-color: var(--ml-surface-3) !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border) !important;\r\n}\r\n\r\n/* ---- Page shell --------------------------------------------------------- */\r\n.ui-pdp-main {\r\n  background-color: transparent !important;\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-pdp-container {\r\n  background-color: var(--ml-surface-1) !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n.ui-pdp-header {\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n\r\n/* ---- Price block -------------------------------------------------------\r\n   Second line, struck original value, subtle/disclaimer and installments are\r\n   coloured in 30-text.css. Only the discount label is new here. */\r\n.ui-pdp-price__discount {\r\n  color: var(--ml-green) !important;\r\n}\r\n.ui-pdp-price__disclaimer {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n\r\n/* ---- Buy box -----------------------------------------------------------\r\n   Colour-only on the family: the CTA buttons inside are `.andes-button*` and\r\n   must keep their own brand fills from 40-forms.css. */\r\n[class^=\"ui-pdp-buybox\"],\r\n[class*=\" ui-pdp-buybox\"] {\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n\r\n/* Benefits strip (\"Compra Protegida\", trust/benefit marks). The indigo icon\r\n   colour is set in 30-text.css; here the strip stops painting #fff. */\r\n[class^=\"ui-pdp-benefits\"],\r\n[class*=\" ui-pdp-benefits\"] {\r\n  background-color: transparent !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n\r\n/* ---- Variations (size, storage, colour) --------------------------------\r\n   Pills are white with a #d5d9d9 outline in the light theme. Selected state\r\n   is matched through the ARIA/state attributes MELI already ships plus their\r\n   `--selected` modifier, so no leaf name is assumed. */\r\n[class^=\"ui-pdp-variations\"],\r\n[class*=\" ui-pdp-variations\"] {\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n[class^=\"ui-pdp-variations\"] select,\r\n[class*=\" ui-pdp-variations\"] select {\r\n  background-color: var(--ml-surface-2) !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border) !important;\r\n}\r\n[class^=\"ui-pdp-variations\"] [class*=\"--selected\"]:not(.andes-button),\r\n[class*=\" ui-pdp-variations\"] [class*=\"--selected\"]:not(.andes-button),\r\n[class^=\"ui-pdp-variations\"] [aria-checked=\"true\"],\r\n[class*=\" ui-pdp-variations\"] [aria-checked=\"true\"],\r\n[class^=\"ui-pdp-variations\"] [aria-pressed=\"true\"],\r\n[class*=\" ui-pdp-variations\"] [aria-pressed=\"true\"] {\r\n  background-color: var(--ml-surface-3) !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-blue) !important;\r\n}\r\n\r\n/* Colour swatches: a dot on a white ring. */\r\n[class^=\"ui-pdp-color-variation-picker\"],\r\n[class*=\" ui-pdp-color-variation-picker\"] {\r\n  color: var(--ml-text-secondary) !important;\r\n  border-color: var(--ml-border) !important;\r\n}\r\n[class^=\"ui-pdp-color-variation-picker\"] [class*=\"--selected\"],\r\n[class*=\" ui-pdp-color-variation-picker\"] [class*=\"--selected\"],\r\n[class^=\"ui-pdp-color-variation-picker\"] [aria-checked=\"true\"],\r\n[class*=\" ui-pdp-color-variation-picker\"] [aria-checked=\"true\"] {\r\n  border-color: var(--ml-blue) !important;\r\n}\r\n\r\n/* ---- Seller / shipping / pickup / warranty -----------------------------\r\n   Small info cards around the buy box. Background only: their text colours\r\n   are owned by 30-text.css and must not be flattened here. */\r\n[class^=\"ui-pdp-seller\"],\r\n[class*=\" ui-pdp-seller\"],\r\n[class^=\"ui-pdp-shipping\"],\r\n[class*=\" ui-pdp-shipping\"],\r\n[class^=\"ui-pdp-pickup\"],\r\n[class*=\" ui-pdp-pickup\"],\r\n[class^=\"ui-pdp-warranty\"],\r\n[class*=\" ui-pdp-warranty\"] {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n.ui-pdp-seller {\r\n  background-color: var(--ml-surface-1) !important;\r\n}\r\n/* Free-shipping wording inside the delivery calculator keeps the brand green\r\n   affordance; the `.shipping-free` / `.andes-money-amount--free` primitives\r\n   themselves are coloured once in 30-text.css, not re-declared here. */\r\n[class^=\"ui-pdp-shipping\"] .shipping-free,\r\n[class*=\" ui-pdp-shipping\"] .shipping-free {\r\n  color: var(--ml-green) !important;\r\n}\r\n\r\n/* ---- Description -------------------------------------------------------- */\r\n[class^=\"ui-pdp-description\"],\r\n[class*=\" ui-pdp-description\"] {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n[class^=\"ui-pdp-description\"] h2,\r\n[class*=\" ui-pdp-description\"] h2,\r\n[class^=\"ui-pdp-description\"] h3,\r\n[class*=\" ui-pdp-description\"] h3,\r\n[class^=\"ui-pdp-description\"] h4,\r\n[class*=\" ui-pdp-description\"] h4 {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n\r\n/* ---- Technical specs (striped table) -----------------------------------\r\n   `.andes-table*`, `.ui-vpp-striped-specs*` rows/columns, their surfaces and\r\n   the odd/even striping are done in 20-cards.css and not repeated here. What\r\n   that file leaves open is the muted \"id\" column MELI renders in #666. */\r\n.ui-vpp-striped-specs__row__column--id {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* ---- Reviews -----------------------------------------------------------\r\n   Comment text, titles, dates and the rating average are coloured in\r\n   30-text.css. Star/bar fills are the brand mark: they are left exactly as\r\n   MELI draws them (yellow on dark is the recognised affordance). */\r\n[class^=\"ui-review\"],\r\n[class*=\" ui-review\"],\r\n[class^=\"ui-reviews\"],\r\n[class*=\" ui-reviews\"] {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n[class^=\"ui-review\"] progress,\r\n[class*=\" ui-review\"] progress,\r\n[class^=\"ui-reviews\"] progress,\r\n[class*=\" ui-reviews\"] progress {\r\n  background-color: var(--ml-surface-3) !important;\r\n  /* `accent-color`, not `color`: this is the star/bar fill (the one place\r\n     --ml-yellow is allowed — it is a brand mark, not text) and it needs to\r\n     override the UA light-theme accent, not paint a label. */\r\n  accent-color: var(--ml-yellow) !important;\r\n  color: var(--ml-yellow) !important;\r\n}\r\n\r\n/* ---- Questions & answers ------------------------------------------------ */\r\n[class^=\"ui-pdp-questions\"],\r\n[class*=\" ui-pdp-questions\"] {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n.ui-pdp-questions__thread {\r\n  background-color: var(--ml-surface-1) !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border: 1px solid var(--ml-border-subtle) !important;\r\n}\r\n\r\n/* ---- Product video -----------------------------------------------------\r\n   Framed on a dark well. NEVER filtered, dimmed or opacitied (S3). */\r\n[class^=\"ui-video\"],\r\n[class*=\" ui-video\"] {\r\n  background-color: var(--ml-surface-2) !important;\r\n  border-color: var(--ml-border) !important;\r\n}\r\n\r\n/* ---- Recommendations (\"Productos relacionados\", ui-vip) ----------------\r\n   `.recos-polycard` and the list/grid card surfaces are already dark from\r\n   20-cards.css; this only neutralises the rails and headers. */\r\n[class^=\"ui-recommendations\"],\r\n[class*=\" ui-recommendations\"] {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n[class^=\"ui-recommendations\"] h2,\r\n[class*=\" ui-recommendations\"] h2,\r\n[class^=\"ui-vip\"],\r\n[class*=\" ui-vip\"] {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n\r\n/* ---- Generic MELI box --------------------------------------------------\r\n   `.ui-box` is the small white panel used for shipping/warranty summaries on\r\n   the PDP and the cart. Styled once here, reused by 80-commerce.css. */\r\n.ui-box {\r\n  background-color: var(--ml-surface-1) !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n/* ============================================================================\r\n   PDP colour leftovers — measured on a real /p/MCO* page AFTER the first pass.\r\n   MELI has a `ui-pdp-color--<NAME>` modifier family (like BEM + a palette),\r\n   which is a stable hook: map the suffix instead of chasing leaves.\r\n   ========================================================================== */\r\n\r\n/* Family hook: ui-pdp-color--BLACK / --GRAY / --DARK are literal light-theme\r\n   text colours (rgba(0,0,0,.9) and rgba(0,0,0,.55)). */\r\n[class*=\"ui-pdp-color--BLACK\"],\r\n[class*=\"ui-pdp-color--DARK\"] {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n[class*=\"ui-pdp-color--GRAY\"],\r\n[class*=\"ui-pdp-color--GREY\"] {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n.ui-pdp-subtitle,\r\n.ui-pdp-review__rating,\r\n.ui-pdp-review__amount,\r\n.ui-pdp-review__label,\r\n.ui-pdp-promotions-pill-label__text,\r\n.ui-pdp-stock-information,\r\n.ui-pdp-stock-information__label,\r\n[class*=\"ui-pdp-stock\"] {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n.ui-pdp-related-search__item,\r\n.ui-pdp-related-search__link,\r\n.ui-pdp-outside_variations__title__label,\r\n.ui-pdp-outside_variations__title__value,\r\n.ui-pdp-products__label,\r\n.ui-vpp-striped-specs__header,\r\n.ui-vpp-striped-specs__header__text,\r\n.ui-recommendations-font-color--BLACK {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-recommendations-font-color--GRAY {\r\n  color: var(--ml-text-muted) !important;\r\n}\r\n\r\n/* The benefits list under the buybox (\"Devolución gratis\", \"Compra Protegida\")\r\n   is a set of links, so it gets the link colour, not grey. */\r\n.ui-pdp-action-modal__link,\r\n[class*=\"ui-pdp-benefits\"] a,\r\n[class*=\"ui-pdp-benefits\"] .ui-pdp-action-modal__link {\r\n  color: var(--ml-blue) !important;\r\n}\r\n\r\n/* Decorative diamond/separator above the promotions box is painted white. */\r\n.ui-pdp-promotions-pill,\r\n.ui-pdp-promotions-pill__label,\r\n.ui-pdp-promotions-pill__container {\r\n  background-color: var(--ml-green-tint) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n.ui-pdp-promotions-pill::before,\r\n.ui-pdp-promotions-pill__label::before,\r\n.ui-pdp-promotions-pill__container::before,\r\n.ui-pdp-promotions-pill::after,\r\n.ui-pdp-promotions-pill__label::after {\r\n  background-color: var(--ml-green-tint) !important;\r\n  border-color: var(--ml-green-tint) !important;\r\n}\r\n\r\n/* ---- Second PDP pass: reviews, variation pills, buybox meta -------------\r\n   Measured with the theme applied. The review subsystem is its own namespace\r\n   (348 nodes) and has its own titles/labels/dates. */\r\n.ui-review-capability__header__title,\r\n.ui-review-capability__reviews-carousel__title,\r\n.ui-review-capability__summary__description__title,\r\n.ui-review-capability__summary__plain_text__sum,\r\n.ui-review-capability-comments__comment__content,\r\n.ui-review-capability-comments__comment__title,\r\n.ui-review-comments__comment__content,\r\n.ui-review-capability__rating__average,\r\n.ui-review-capability__rating__label,\r\n.total-opinion,\r\n.ui-reviews-label-icon,\r\n.ui-review-capability-comments__comment__date,\r\n.ui-review-capability-comments__comment__meta {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-review-capability-comments__comment__date,\r\n.ui-review-capability-comments__comment__meta,\r\n.ui-review-capability__summary__description__text,\r\n.ui-review-capability__status__text {\r\n  color: var(--ml-text-muted) !important;\r\n}\r\n/* Rating histogram — NO VENDOR PSEUDO-ELEMENTS HERE.\r\n   An earlier pass assumed MELI rendered each star row as <progress> and wrote\r\n   ::-webkit-progress-value / ::-moz-progress-bar rules. That was wrong: the\r\n   histogram is a <div> track plus a <span> fill painted with a gradient, and\r\n   the `.ui-review-capability__rating__progress` class those rules targeted does\r\n   not exist in the DOM at all (verified: 0 <progress> and 0 <meter> on every\r\n   page measured). The real styling lives in 98-late-fixes.css under\r\n   `li.ui-review-capability-rating__level`.\r\n\r\n   The dead rules were also the source of the Stylus editor warning: any rule\r\n   mentioning a vendor pseudo-element trips its \"Unexpected prefix\" linter even\r\n   when the selector can never match. Removed rather than split. */\r\n/* Star glyphs are an icon font too; they must follow the yellow, not the text. */\r\n[class*=\"ui-review-capability__rating\"] i[class*=\"star\"],\r\n[class*=\"ui-review-capability__rating\"] [class^=\"ui-review-star\"],\r\n[class^=\"ui-review-star\"],\r\n[class*=\" ui-review-star\"],\r\n.ui-pdp-review__stars i,\r\n.ui-pdp-review__stars svg {\r\n  color: var(--ml-yellow) !important;\r\n  fill: var(--ml-yellow) !important;\r\n}\r\n\r\n/* Variation pills: unselected are dark text on dark; selected is brand blue. */\r\n[class*=\"ui-pdp-variations\"] button,\r\n[class*=\"ui-pdp-variations\"] [role=\"radio\"],\r\n[class*=\"ui-pdp-outside_variations\"] button,\r\n[class*=\"ui-pdp-outside_variations\"] [role=\"radio\"],\r\n.ui-pdp-variations__picker button,\r\n.ui-pdp-variations__picker span {\r\n  background-color: var(--ml-surface-2) !important;\r\n  border-color: var(--ml-border) !important;\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n[class*=\"ui-pdp-variations\"] [aria-checked=\"true\"],\r\n[class*=\"ui-pdp-variations\"] [aria-selected=\"true\"],\r\n[class*=\"ui-pdp-variations\"] [class*=\"--selected\"],\r\n[class*=\"ui-pdp-outside_variations\"] [class*=\"--selected\"] {\r\n  background-color: var(--ml-blue-fill) !important;\r\n  border-color: var(--ml-blue-fill) !important;\r\n  color: var(--ml-text-on-brand) !important;\r\n}\r\n.ui-pdp-variations__title,\r\n.ui-pdp-outside_variations__title {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* \"Stock disponible\" + the Full line under it. */\r\n.ui-pdp-stock-information,\r\n.ui-pdp-stock-information__title,\r\n[class*=\"ui-pdp-stock\"] ,\r\n.ui-pdp-promotions-pill-label,\r\n.ui-pdp-promotions-pill-label__text,\r\n.ui-pdp-promotions-pill__label,\r\n.ui-pdp-promotions-pill__label-title,\r\n.ui-pdp-promotions-pill__label-text {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.ui-pdp-promotions-pill__label b,\r\n.ui-pdp-promotions-pill__label strong {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n\r\n/* Seller sales counter (\"+100 mil ventas\"). */\r\n.ui-pdp-seller__sales,\r\n.ui-pdp-seller__sales-description,\r\n[class*=\"ui-seller\"] [class*=\"sales\"] {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* Other-sellers list (\"29 productos nuevos desde …\"). */\r\n.ui-pdp-other-sellers-item__tag,\r\n.ui-pdp-other-sellers-item__title,\r\n[class*=\"ui-pdp-other-sellers\"] {\r\n  background-color: var(--ml-surface-2) !important;\r\n  color: var(--ml-text-primary) !important;\r\n  border-color: var(--ml-border) !important;\r\n}\r\n.ui-box-component__title,\r\n.ui-box__title {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.nav-assistant-heading {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n/* The gallery thumbnails are letterboxes too: their leftover band must stay\r\n   light, otherwise the photo reads as a dark hole. Colour lives in\r\n   --ml-thumb-plate (98-late-fixes.css). */\r\n.ui-pdp-gallery__zoom-container,\r\n.ui-pdp-thumbnail__picture {\r\n  background-color: var(--ml-surface-2) !important;\r\n  border-color: var(--ml-border) !important;\r\n}\r\n.andes-thumbnail,\r\n.andes-thumbnail--circle {\r\n  border-color: var(--ml-border) !important;\r\n}\r\n[class*=\"ui-pdp\"] button {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n\n/* ---- \"Opiniones\" hub (my-reviews) ---------------------------------------\n   This page reuses the `ui-reviews-*` namespace but adds a COLOUR MODIFIER as\n   a second class: `ui-reviews-color--handes-green-500`. That modifier has\n   higher specificity than the namespace rule above, and it sets the light\n   theme's green/grey, so labels stayed at rgba(0,0,0,.55) — the reported\n   \"los títulos y las fechas de las opiniones no se leen\".\n\n   Note the typo is MELI's own: `handes-` (an `andes-` + `h` typo) is shipped in\n   production, so it must be matched literally. */\n[class*=\"ui-reviews-color--handes-green\"],\n[class*=\"ui-reviews-color--andes-green\"],\n[class*=\"ui-reviews-color--green\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n/* Titles inside the pending-review cards are content, not metadata. */\n[class*=\"ui-reviews\"] [class*=\"--title\"],\n[class*=\"ui-reviews\"] h1,\n[class*=\"ui-reviews\"] h2,\n[class*=\"ui-reviews\"] h3,\n[class*=\"ui-reviews\"] h4,\n[class*=\"ui-reviews\"] [class*=\"product-title\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n/* Dates and counters are deliberately quieter than titles. */\n[class*=\"ui-reviews\"] [class*=\"--date\"],\n[class*=\"ui-reviews\"] [class*=\"--subtitle\"],\n[class*=\"ui-reviews\"] [class*=\"--count\"] {\n  color: var(--ml-text-muted, #7c8794) !important;\n}\n\n/* ---- Pending-review star selector --------------------------------------\n   The star row is NOT an icon font and NOT <progress>: it is a 5-item\n   `andes-list` where each item holds an inline `<svg>` whose `<path>` is\n   `fill=\"currentColor\"` and whose computed `color` is rgba(0,0,0,.25) — a\n   near-black wash meant for the white theme. On the dark card it collapsed\n   into a solid dark blob, exactly as reported (\"el widget de estrellas es un\n   manchón oscuro\").\n\n   `fill=currentColor` means re-tinting `color` is enough; no per-path rule is\n   needed and the icons stay crisp vectors. */\nul[class*=\"rating-select\"] li svg,\nul[class*=\"rating-select\"] svg,\n[class*=\"rating-select__item\"] svg {\n  color: var(--ml-border-strong, #3d4653) !important; /* empty star */\n}\n/* A rated item marks the filled stars; they keep MELI's yellow (brand mark). */\nul[class*=\"rating-select\"] li:not([class*=\"unselected\"]) svg,\n[class*=\"rating-select__item\"]:not([class*=\"unselected\"]) svg {\n  color: var(--ml-yellow, #ffe600) !important;\n}\n/* Hover preview must read as \"this many stars\". */\nul[class*=\"rating-select\"] li:hover svg {\n  color: var(--ml-yellow, #ffe600) !important;\n}\n\n/* ---- my-reviews pending cards: `ui-card-pending-*` ----------------------\n   A fourth namespace on the same page. The purchase date lives in\n   `ui-card-pending-product-date > .ui-reviews-label` and keeps the light\n   theme's rgba(0,0,0,.55), so it rendered at 2.1:1 on the dark row. */\n[class^=\"ui-card-pending\"],\n[class*=\" ui-card-pending\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n[class*=\"ui-card-pending-product-date\"],\n[class*=\"ui-card-pending\"] [class*=\"--date\"] {\n  color: var(--ml-text-muted, #7c8794) !important;\n}\n[class*=\"ui-card-pending\"] [class*=\"product-date\"] .ui-reviews-label,\n[class*=\"ui-card-pending\"] [class*=\"product-date\"] span {\n  color: var(--ml-text-muted, #7c8794) !important;\n}\n\n/* ===== 80-commerce.css ===== */\n/* ============================================================================\n   80-commerce.css — cart (…/gz/cart*) and checkout.\n\n   Two subsystems meet here:\n   • `cl-*` — the cart/checkout layout cards.\n   • `poly-*` / `andes-*` — the product rows and controls inside them, which\n     come from the same design system as the results grid.\n\n   The measured map (NOTAS §7.1/§7.3) names the cart primitives only at family\n   level: `cl-grouped-card*`, `cl-card-header*`, `cl-image-label*`,\n   `andes-input-stepper*`, `poly-coupons__pill`, and `checkout-*` /\n   coupon / delivery / totals as *families*. Leaf names inside those families\n   are not measured, so they are matched as families\n   (`[class^=\"x\"], [class*=\" x\"]`) instead of being invented as BEM leaves —\n   that is also what makes the file survive a MELI rename (S4).\n\n   Already dark elsewhere — intentionally not repeated here:\n     .cl-grouped-card*, .cl-card-header*, .cl-image-label* ... 20-cards.css\n     .poly-card* surfaces + hover ........................... 20-cards.css\n     .poly-card--checkbox / --list / --list-card /\n       --disabled / --no-highlight / --highlight-component .. 20-cards.css\n     .andes-input-stepper* (container, wrapper, content,\n       button, value, helper, disabled) ..................... 40-forms.css\n     .andes-money-amount*, .andes-badge* .................... 30-text.css /\n                                                             40-forms.css\n     .andes-button--loud (checkout CTA) ..................... 40-forms.css\n     .poly-coupons__pill .................................... 50-coverage.css\n     .ui-box ................................................ 70-pdp.css\n   ========================================================================== */\n\n/* ---- Cart rows ---------------------------------------------------------\n   Each item is a `.cl-grouped-card` (surface from 20-cards.css). The row\n   bodies and action strips inside are re-painted #fff by MELI, and the\n   divider between items is #ededed. */\n[class^=\"cl-grouped-card\"],\n[class*=\" cl-grouped-card\"] {\n  border-color: var(--ml-border-subtle) !important;\n}\n[class^=\"cl-grouped-card\"] > div,\n[class*=\" cl-grouped-card\"] > div,\n[class^=\"cl-grouped-card\"] > section,\n[class*=\" cl-grouped-card\"] > section,\n[class^=\"cl-grouped-card\"] > ul,\n[class*=\" cl-grouped-card\"] > ul {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Cart header -------------------------------------------------------\n   `.cl-card-header` is a white band holding the group title. */\n[class^=\"cl-card-header\"],\n[class*=\" cl-card-header\"] {\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n[class^=\"cl-card-header\"] h2,\n[class*=\" cl-card-header\"] h2,\n[class^=\"cl-card-header\"] h3,\n[class*=\" cl-card-header\"] h3 {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Image labels on cart thumbnails (\"Última unidad\", scarcity) -------\n   Surface, background and text colour are already set by 20-cards.css, which\n   is why this file does NOT restate them. Nothing to add: the label is a\n   self-contained overlay and its own `color` is inherited from the card. */\n\n/* ---- Quantity stepper: only what 40-forms.css leaves open --------------\n   The `<input>` itself is not covered there, and it is what keeps the middle\n   of the stepper white. */\n.andes-input-stepper input {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: transparent !important;\n}\n\n/* ---- Coupon field and coupon rows --------------------------------------\n   The input is an `.andes-form-control` (40-forms.css); its wrapper and the\n   applied-coupon rows are not. Applied coupons are a mint surface on light,\n   so they become --ml-green-tint and keep green money text (NOT text-green\n   on a green fill — the tint is a surface, the text is --ml-green). */\n[class^=\"coupon\"],\n[class*=\" coupon\"],\n[class^=\"cl-coupon\"],\n[class*=\" cl-coupon\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n[class^=\"coupon\"] [class*=\"row\"],\n[class*=\" coupon\"] [class*=\"row\"],\n[class^=\"cl-coupon\"] [class*=\"row\"],\n[class*=\" cl-coupon\"] [class*=\"row\"],\n[class^=\"coupon\"][class*=\"applied\"],\n[class*=\" coupon\"][class*=\"applied\"] {\n  background-color: var(--ml-green-tint) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n[class^=\"coupon\"] [class*=\"row\"] .andes-money-amount,\n[class*=\" coupon\"] [class*=\"row\"] .andes-money-amount,\n[class^=\"cl-coupon\"] [class*=\"row\"] .andes-money-amount,\n[class*=\" cl-coupon\"] [class*=\"row\"] .andes-money-amount,\n[class^=\"coupon\"] .andes-money-amount,\n[class*=\" coupon\"] .andes-money-amount {\n  color: var(--ml-green) !important;\n}\n\n/* ---- Shipping / delivery option rows -----------------------------------\n   Radio + label pairs in a white well; the selected one gets a blue border.\n   The radio control itself is 40-forms.css, so only the row is touched. */\n[class*=\"shipping-option\"],\n[class*=\"delivery-option\"],\n[class^=\"checkout-shipping\"],\n[class*=\" checkout-shipping\"],\n[class^=\"checkout-delivery\"],\n[class*=\" checkout-delivery\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n[class*=\"shipping-option\"]:hover,\n[class*=\"delivery-option\"]:hover {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n/* Selected row — MELI's own pattern is the blue tint + blue border pair. */\n[class*=\"shipping-option\"][class*=\"--selected\"],\n[class*=\"delivery-option\"][class*=\"--selected\"],\n[class*=\"shipping-option\"] [aria-checked=\"true\"],\n[class*=\"delivery-option\"] [aria-checked=\"true\"] {\n  background-color: var(--ml-blue-tint) !important;\n  border-color: var(--ml-blue) !important;\n}\n\n/* ---- Checkout shell and steps ------------------------------------------\n   `[class^=\"checkout-\"], [class*=\" checkout-\"]` is a family reset, so it sits\n   BEFORE the component rules below and every component rule carries one more\n   compound than it (`.checkout-*--card`, `.checkout-*[class*=\"payment\"]`), so\n   source order never decides the outcome. */\n[class^=\"checkout-\"],\n[class*=\" checkout-\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n/* Where a `.checkout-*` panel is a real card, MELI marks it by modifier; those\n   get the card surface instead of dissolving. */\n[class^=\"checkout-\"][class*=\"--card\"],\n[class*=\" checkout-\"][class*=\"--card\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n/* Step indicator strip + current step. */\n[class^=\"checkout-\"] [class*=\"progress\"],\n[class*=\" checkout-\"] [class*=\"progress\"],\n[class*=\"step-indicator\"],\n[class*=\"step\"][class*=\"--current\"] {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n[class*=\"step\"][class*=\"--completed\"] {\n  color: var(--ml-green) !important;\n}\n\n/* ---- Payment method cards ----------------------------------------------\n   Each method is a selectable card; selected = blue outline, same primitive\n   as the delivery rows. Compound specificity beats the family reset above. */\n[class^=\"checkout-\"] [class*=\"payment\"],\n[class*=\" checkout-\"] [class*=\"payment\"] {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n}\n[class^=\"checkout-\"] [class*=\"payment\"]:hover,\n[class*=\" checkout-\"] [class*=\"payment\"]:hover {\n  background-color: var(--ml-surface-2) !important;\n}\n[class^=\"checkout-\"] [class*=\"payment\"][class*=\"--selected\"],\n[class*=\" checkout-\"] [class*=\"payment\"][class*=\"--selected\"],\n[class^=\"checkout-\"] [class*=\"payment\"][aria-checked=\"true\"],\n[class*=\" checkout-\"] [class*=\"payment\"][aria-checked=\"true\"] {\n  background-color: var(--ml-blue-tint) !important;\n  border-color: var(--ml-blue) !important;\n}\n\n/* ---- Totals ----------------------------------------------------------------\n   The summary the user is about to pay: subtotal, shipping, total. Money text\n   must never be dimmed here — rows are transparent so amounts inherit primary\n   and the struck/previous price keeps its muted styling from 30-text.css.\n   The panel and the row reset are two compounds apart in specificity\n   (`[class*=\"totals\"]` vs `[class*=\"totals\"][class*=\"container\"]`), so source\n   order never flattens the panel. */\n[class*=\"totals\"][class*=\"container\"],\n[class*=\"totals\"][class*=\"--card\"],\n[class*=\"totals-summary\"],\n[class^=\"cl-summary\"][class*=\"--card\"],\n[class*=\" cl-summary\"][class*=\"--card\"] {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n[class*=\"totals\"],\n[class^=\"cl-summary\"],\n[class*=\" cl-summary\"] {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n[class*=\"totals\"] [class*=\"label\"] {\n  color: var(--ml-text-secondary) !important;\n}\n[class*=\"totals\"] [class*=\"--total\"],\n[class*=\"totals\"] [class*=\"grand\"] {\n  border-top: 1px solid var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n/* Free shipping inside the summary keeps the brand green, not muted grey. */\n[class*=\"totals\"] [class*=\"free\"] {\n  color: var(--ml-green) !important;\n}\n\n/* ---- Empty cart --------------------------------------------------------- */\n[class^=\"cl-empty\"],\n[class*=\" cl-empty\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n}\n/* ============================================================================\n   Cart verification pass — measured on `/gz/cart/v2` with the theme applied.\n   Note on the cart URL: `/gz/cart/v2` is MELI's internal route (\"gz\" gateway,\n   \"v2\" of the cart app). It is the canonical cart URL; nothing to normalise.\n   ========================================================================== */\n\n/* Selected-attributes line (\"Color: Negro\") inside the cart row. */\n.poly-attributes_selected,\n.poly-attributes_selected__item,\n.poly-attributes,\n.poly-component__attributes-selected,\n.poly-component__attributes {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* Coupon discount label on the price line (\"con Cupón\"). */\n.cl-price__discount-label,\n.cl-price__discount,\n[class*=\"cl-price__discount\"] {\n  color: var(--ml-green) !important;\n}\n.cl-price,\n.cl-price__value,\n.cl-price__amount {\n  color: var(--ml-text-primary) !important;\n}\n\n/* Recommendations rail under the cart. */\n.recommendations-wrapper,\n[class*=\"recommendations-wrapper\"] {\n  background-color: var(--ml-surface-0) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* Header user menu: \"Compras\" shortcut rows and the older account block.\n   `.user-menu--hidden` is measured markup, not a mistake: MELI keeps it in the\n   DOM and flips its visibility. Styling it costs nothing and prevents a white\n   flash when the menu opens. */\n.user-menu__shortcuts,\n.user-menu__shortcuts a,\n.user-menu__shortcuts li a,\n.user-menu__shortcuts-tag,\n.user-menu__old,\n.user-menu__old a,\n.nav-header-user-layer a {\n  color: var(--ml-text-primary) !important;\n}\n.user-menu__old,\n.nav-header-user-layer {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* Category panel header (\"Tecnología\") — the div carries no class at all, so\n   the only handle is the parent's namespace. */\n.nav-categs-detail__header,\n.nav-categs-detail__header div,\n.nav-categs-detail__header span,\n.nav-categs-detail > div {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ===== 89-andes-ui.css ===== */\n/* ===========================================================================\n   89-andes-ui.css — \"andes-ui-*\" generation, on the HOST page\n   ===========================================================================\n\n   MELI is migrating from `andes-*` (the classic design system this theme was\n   written against) to a newer, differently-named generation: `andes-ui-*`.\n   Earlier passes only met it inside an iframe (the address picker, see\n   99-iframes.css), so it was handled there as a widget concern.\n\n   It is now rendering directly on normal host pages. `/ayuda` is the measured\n   case: it is built entirely from this generation and had NOT A SINGLE rule\n   applying to it — the pages looked untouched, not merely imperfect. Adding it\n   as its own file, rather than patching each page, is the same decision made\n   for every other subsystem in this theme.\n\n   MEASURED ON /ayuda (light theme):\n     .template.bg_primary                      rgb(237,237,237) page shell\n     .andes-ui-card(--default)                 rgb(255,255,255) cards\n     .folder-module__card                      white\n     .page-content__card                       white\n     .contact-module                           white\n     .andes-ui-typography                      rgba(0,0,0,.9)    text\n     .andes-ui-structured-item-content__title  rgba(0,0,0,.9)    titles\n     .option-help                              rgba(0,0,0,.9)    nav label\n\n   NOTE ON PREFIXES: `[class^=\"andes-ui\"]` / `[class*=\" andes-ui\"]` are safe\n   anchors here (the token is at a class boundary), unlike the substring\n   wildcards that caused the hero-image bug documented in 92-landings.css.\n   =========================================================================== */\n\n/* ---- Page shell --------------------------------------------------------- */\n.template,\n[class*=\"bg_primary\"],\n[class*=\"bg-secondary\"] {\n  background-color: var(--ml-surface-0, #12151a) !important;\n  background-image: none !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* ---- Cards of this generation ------------------------------------------ */\n[class^=\"andes-ui-card\"],\n[class*=\" andes-ui-card\"],\n[class*=\"folder-module__card\"],\n[class*=\"page-content__card\"],\n[class*=\"contact-module\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n\n/* ---- Typography primitives --------------------------------------------- */\n/* These carry the colour themselves at rgba(0,0,0,.9) / .55, so inheritance\n   never reaches them. */\n[class^=\"andes-ui-typography\"],\n[class*=\" andes-ui-typography\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"structured-item-content__title\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"structured-item-content__description\"],\n[class*=\"structured-item-content__subtitle\"],\n[class*=\"andes-ui-typography-body\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n/* Headings inside this generation are bold body text, not h1/h2 semantics. */\n[class*=\"andes-ui-typography-heading\"],\n[class*=\"andes-ui-typography--type-head\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* ---- Links and buttons -------------------------------------------------- */\n[class^=\"andes-ui\"] a,\n[class*=\" andes-ui\"] a {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n[class*=\"andes-ui-button\"] {\n  border-color: var(--ml-border, #2f3742) !important;\n}\n[class*=\"andes-ui-button\"][class*=\"secondary\"],\n[class*=\"andes-ui-button\"][class*=\"neutral\"],\n[class*=\"andes-ui-button\"][class*=\"outline\"],\n[class*=\"andes-ui-button\"][class*=\"tertiary\"] {\n  background-color: var(--ml-surface-2, #1f242c) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* ---- Inputs / search ---------------------------------------------------- */\n[class^=\"andes-ui\"] :is(input, textarea, select),\n[class*=\" andes-ui\"] :is(input, textarea, select) {\n  background-color: var(--ml-surface-2, #1f242c) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border, #2f3742) !important;\n}\n[class^=\"andes-ui\"] :is(input, textarea)::placeholder,\n[class*=\" andes-ui\"] :is(input, textarea)::placeholder {\n  color: var(--ml-text-disabled, #5a6472) !important;\n}\n\n/* ---- Dividers, list rows, sheets --------------------------------------- */\n[class^=\"andes-ui\"],\n[class*=\" andes-ui\"] {\n  border-color: var(--ml-border-subtle, #242a33);\n}\n[class*=\"structured-item\"],\n[class*=\"folder-module\"],\n[class*=\"page-content\"] {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n\n/* ---- Header entry point ------------------------------------------------- */\n/* The help link in the navbar belongs to the OLD header but points here; its\n   label was the only other dark text left on the page. */\n.option-help,\n.nav-header .option-help a {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* ---- Colour modifiers of this generation win on specificity -------------\n   The measured element carries THREE classes, all from this generation:\n     class=\"andes-ui-typography andes-ui-structured-item-content__title\n            andes-ui-typography--color-primary\"\n   `[class^=\"andes-ui-typography\"]` matches it, but MELI's own modifier\n   (`.andes-ui-typography--color-primary`) is declared later with the same\n   specificity, so it re-asserts rgba(0,0,0,.9).\n\n   `[class*=\"…\"]` would match the token anywhere in the attribute, which is\n   the wildcard shape that caused the hero-image bug; `~=` is different — it\n   matches a WHOLE class token and cannot swallow content classes. These rules\n   therefore use the modifier token as the anchor, which is both specific and\n   scoped by construction. */\n[class*=\"andes-ui-typography--color-primary\"],\n[class*=\"andes-ui-typography--color-body\"],\n[class*=\"andes-ui-typography--color-default\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"andes-ui-typography--color-secondary\"],\n[class*=\"andes-ui-typography--color-tertiary\"],\n[class*=\"andes-ui-typography--color-muted\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n[class*=\"andes-ui-typography--color-link\"],\n[class*=\"andes-ui-typography--color-action\"] {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n/* Any remaining title/heading token on its own. */\n[class*=\"structured-item-content__title\"],\n[class*=\"structured-item-content__title\"] * {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* Same modifier, but the competitor is more specific than one attribute\n   selector: MELI combines the colour modifier with a size/weight class\n   (`--color-primary` + `--type-body` + `--size-large` + `-body-large-default`).\n   Requiring BOTH the typography AND the colour token raises our specificity to\n   0,2,0 without touching anything outside this generation. */\n[class*=\"andes-ui-typography\"][class*=\"--color-primary\"],\n[class*=\"andes-ui-typography\"][class*=\"--color-body\"],\n[class*=\"andes-ui-typography\"][class*=\"--color-default\"],\n[class*=\"structured-item-content__title\"][class*=\"andes-ui\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"andes-ui-typography\"][class*=\"--color-secondary\"],\n[class*=\"andes-ui-typography\"][class*=\"--color-tertiary\"],\n[class*=\"andes-ui-typography\"][class*=\"--color-muted\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n\n/* ---- -webkit-text-fill-color overrides `color` --------------------------\n   Root cause of \"my colour rule matches but the text stays black\":\n\n   This generation paints text with `-webkit-text-fill-color`, which WINS over\n   `color` for the visible glyphs, no matter how specific or how `!important`\n   the `color` declaration is. Measured: a `html body div[...][...][...]\n   { color: rgb(1,1,1) !important }` rule and an `@layer` variant BOTH left the\n   rendered colour at rgba(0,0,0,.9), because only `color` was being contested.\n\n   So every text rule for this generation must set BOTH properties. The same\n   trap can hit any subsystem that uses fill-color; when a \"colour rule does\n   nothing\" case appears, check `-webkit-text-fill-color` on the computed style\n   before touching specificity. */\n[class*=\"andes-ui-typography\"],\n[class*=\"andes-ui-typography\"] *,\n[class*=\"structured-item-content__title\"],\n[class*=\"structured-item-content__title\"] * {\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"andes-ui-typography\"][class*=\"--color-secondary\"],\n[class*=\"andes-ui-typography\"][class*=\"--color-tertiary\"],\n[class*=\"andes-ui-typography\"][class*=\"--color-muted\"],\n[class*=\"structured-item-content__description\"] {\n  -webkit-text-fill-color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n[class*=\"andes-ui-typography\"][class*=\"--color-link\"],\n[class*=\"andes-ui-typography\"][class*=\"--color-action\"] {\n  -webkit-text-fill-color: var(--ml-blue, #5b9bff) !important;\n}\n\n/* `andes-ui-header` primitive: a white bar by default. Used by the floating\n   chat popup on /ayuda and available to any other MELI surface, so it is\n   themed once here instead of per widget. */\n.andes-ui-header,\n[class*=\"andes-ui-header__content_wrapper\"],\n[class*=\"andes-ui-header__content\"] {\n  background-color: transparent !important;\n  background-image: none !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.andes-ui-header [class*=\"title\"],\n.andes-ui-header h1,\n.andes-ui-header h2 {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* ===== 90-account.css ===== */\n/* ============================================================================\n   90-account.css — seller hub (vendedores.mercadolibre.com.co), my account,\n   purchases, messages, favourites. These pages are *panel* pages: a tinted\n   lavender canvas (rgb(231,233,243)) with white `.module-card` tiles on top.\n\n   Measured surface primitives used below: `.module-card*`, `.tasks-card__subcard`,\n   `.control-panel__segment`, `.recommendation-card-desktop`,\n   `.filter-recommendation-card`, `.recommendation_transition_card`,\n   `.recommendation-card__card`, `.seller-monitor__*`, plus the shared\n   `.andes-layout`, `.andes-table*`, `.andes-list*`, `.andes-badge--gray*`.\n\n   Already dark elsewhere — intentionally not repeated here:\n     .module-card*, .tasks-card__subcard, .control-panel__segment,\n       .recommendation-card-desktop, .filter-recommendation-card,\n       .recommendation-card__card, .recommendation_transition_card,\n       .seller-monitor__loading-card / __loading-list ......... 20-cards.css\n     .andes-table* surfaces + stripes ........................ 20-cards.css\n     .andes-badge, --accent, --gray, --gray--quiet,\n       --success, --warning, --danger ......................... 40-forms.css\n     .andes-list / __item + hover ............................ 40-forms.css\n   What remains is the canvas (which 20-cards.css only neutralises to\n   `transparent`, letting MELI's lavender body colour through), the panel chrome\n   MELI re-paints white *inside* a card, the interactive states of the segment\n   tabs, the seller-monitor tiles, and the account list/table row states.\n   ========================================================================== */\n\n/* ---- Seller hub / account canvas ---------------------------------------\n   base.css already sets `body` and `#root-app` to --ml-surface-0; what it does\n   not touch is the seller hub's own `.andes-layout*` canvas, which MELI ships\n   as rgb(231,233,243) — the lavender tint. On the rest of the site the same\n   wrappers carry #f5f5f5. Both land on the page surface here so the white\n   module tiles keep a visible edge. This is a deliberate one-level override of\n   20-cards.css, which only sets `.andes-layout` to `transparent` and therefore\n   leaves MELI's own canvas colour showing through. */\n.andes-layout,\n.andes-layout__main,\n.andes-layout__content,\n.andes-layout__wrapper {\n  background-color: var(--ml-surface-0) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Module cards: panel chrome ----------------------------------------\n   The surface is 20-cards.css. Inside a card MELI paints the header band\n   lavender (rgb(231,233,243)) and the content area #fff.\n   `.filter-recommendation-card` and `.recommendation_transition_card` are\n   deliberately NOT listed: they are complete surfaces in 20-cards.css and\n   restating them here would be an exact duplicate. */\n[class^=\"module-card\"],\n[class*=\" module-card\"],\n.tasks-card,\n.control-panel,\n[class^=\"recommendation-card\"],\n[class*=\" recommendation-card\"],\n[class^=\"seller-monitor\"],\n[class*=\" seller-monitor\"] {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n/* Header band: the lavender tint, on dark. */\n[class^=\"module-card\"] [class*=\"header\"],\n[class*=\" module-card\"] [class*=\"header\"],\n.tasks-card__subcard [class*=\"header\"],\n[class^=\"seller-monitor\"] [class*=\"header\"],\n[class*=\" seller-monitor\"] [class*=\"header\"] {\n  background-color: var(--ml-lavender-tint) !important;\n  color: var(--ml-text-primary) !important;\n  /* --ml-lavender-tint (#171a21) is darker than the card surface it sits on,\n     so the band needs an edge to read as a header rather than a hole. */\n  border-bottom: 1px solid var(--ml-border-subtle) !important;\n}\n/* Nested white body sections dissolve into the card they sit in. */\n[class^=\"module-card\"] > div,\n[class*=\" module-card\"] > div,\n[class^=\"module-card\"] > section,\n[class*=\" module-card\"] > section,\n[class^=\"recommendation-card\"] > div,\n[class*=\" recommendation-card\"] > div {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Seller monitor (the metric cards / charts strip) ------------------\n   Rows, tiles and the empty state are white on lavender in the light theme;\n   the loading card/list are already handled in 20-cards.css. */\n[class^=\"seller-monitor\"],\n[class*=\" seller-monitor\"] {\n  border-color: var(--ml-border-subtle) !important;\n}\n[class^=\"seller-monitor\"] [class*=\"card\"]:not([class*=\"loading\"]),\n[class*=\" seller-monitor\"] [class*=\"card\"]:not([class*=\"loading\"]),\n[class^=\"seller-monitor\"] [class*=\"tile\"],\n[class*=\" seller-monitor\"] [class*=\"tile\"],\n[class^=\"seller-monitor\"] [class*=\"row\"]:not([class*=\"loading\"]),\n[class*=\" seller-monitor\"] [class*=\"row\"]:not([class*=\"loading\"]) {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n/* Metric labels are secondary, the numbers stay primary so they read at a\n   glance. Never colour the value with an accent: it is data, not brand. */\n[class^=\"seller-monitor\"] [class*=\"label\"],\n[class*=\" seller-monitor\"] [class*=\"label\"],\n[class^=\"seller-monitor\"] [class*=\"caption\"],\n[class*=\" seller-monitor\"] [class*=\"caption\"] {\n  color: var(--ml-text-secondary) !important;\n}\n[class^=\"seller-monitor\"] [class*=\"value\"],\n[class*=\" seller-monitor\"] [class*=\"value\"],\n[class^=\"seller-monitor\"] [class*=\"metric\"],\n[class*=\" seller-monitor\"] [class*=\"metric\"] {\n  color: var(--ml-text-primary) !important;\n}\n/* Trend deltas: arrow + percentage. Up is green, down is red; both are text\n   uses, so they get the lightened tokens, not the #f23d4f / #00a650 fills. */\n[class^=\"seller-monitor\"] [class*=\"positive\"],\n[class*=\" seller-monitor\"] [class*=\"positive\"],\n[class^=\"seller-monitor\"] [class*=\"--up\"],\n[class*=\" seller-monitor\"] [class*=\"--up\"] {\n  color: var(--ml-green) !important;\n}\n[class^=\"seller-monitor\"] [class*=\"negative\"],\n[class*=\" seller-monitor\"] [class*=\"negative\"],\n[class^=\"seller-monitor\"] [class*=\"--down\"],\n[class*=\" seller-monitor\"] [class*=\"--down\"] {\n  color: var(--ml-red) !important;\n}\n/* Chart / progress track must not be a white block. */\n[class^=\"seller-monitor\"] progress,\n[class*=\" seller-monitor\"] progress,\n[class^=\"seller-monitor\"] [class*=\"bar\"],\n[class*=\" seller-monitor\"] [class*=\"bar\"] {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* ---- Recommendation cards ---------------------------------------------\n   `.recommendation-card-desktop`, `.recommendation-card__card`,\n   `.filter-recommendation-card` and `.recommendation_transition_card` are\n   surfaces in 20-cards.css. Their text is the part that needs fixing here. */\n.recommendation-card-desktop h2,\n.recommendation-card-desktop h3,\n.recommendation-card-desktop h4,\n.recommendation-card__card h2,\n.recommendation-card__card h3,\n.recommendation-card__card h4,\n.filter-recommendation-card h2,\n.filter-recommendation-card h3,\n.recommendation_transition_card h2,\n.recommendation_transition_card h3 {\n  color: var(--ml-text-primary) !important;\n}\n.recommendation-card-desktop p,\n.recommendation-card__card p,\n.filter-recommendation-card p,\n.recommendation_transition_card p,\n.recommendation-card-desktop [class*=\"description\"],\n.recommendation-card__card [class*=\"description\"],\n.filter-recommendation-card [class*=\"description\"] {\n  color: var(--ml-text-secondary) !important;\n}\n.recommendation-card-desktop:hover,\n.recommendation-card__card:hover,\n.filter-recommendation-card:hover,\n.recommendation_transition_card:hover {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* ---- Control panel segments (tabs / range pills) ----------------------\n   The base segment surface is 20-cards.css. Only the interactive states are\n   added here, and each one carries the compound (`--active` / `:hover` /\n   `[aria-selected]`) that keeps it above that base rule. */\n.control-panel__segment:hover {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-primary) !important;\n}\n.control-panel__segment--active,\n.control-panel__segment--selected,\n.control-panel__segment[aria-selected=\"true\"],\n.control-panel__segment[class*=\"--active\"] {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n\n/* ---- My-account tables -------------------------------------------------\n   `.andes-table*` surfaces/stripes and `.andes-list*` are handled already;\n   the account tables add a #fff hover and link styling of their own. */\n.andes-table__row:hover,\n.andes-table__row--clickable:hover {\n  background-color: var(--ml-surface-2) !important;\n}\n.andes-table__column a,\n.andes-table__row a {\n  color: var(--ml-blue) !important;\n}\n.andes-table__column a:hover {\n  color: var(--ml-blue-fill) !important;\n  text-decoration: underline;\n}\n.andes-table__cell--highlight,\n.andes-table__row--highlight {\n  background-color: var(--ml-blue-tint) !important;\n}\n\n/* ---- My-account lists (purchases, favourites, saved searches) ----------\n   A list row is a white block with a #ededed divider; hover is rgba(0,0,0,.04)\n   which is invisible on dark.\n   `.andes-list__item` chrome, hover and selected state are 40-forms.css and are\n   deliberately NOT overridden here — that primitive is also the drop-down\n   picker, and an account file must not shift its interaction colours. Only the\n   #ededed divider is refined, plus the muted sub-line text. */\n.andes-list__item {\n  border-color: var(--ml-border-subtle) !important;\n}\n.andes-list__item [class*=\"subtitle\"],\n.andes-list__item [class*=\"description\"] {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Gray badges on these panels --------------------------------------\n   `.andes-badge--gray` and `--gray--quiet` are already dark from 40-forms.css.\n   Only the variant that sits *on* the lavender header band needs a slightly\n   lighter surface to stay distinguishable from its parent. */\n[class^=\"module-card\"] [class*=\"header\"] .andes-badge--gray,\n[class*=\" module-card\"] [class*=\"header\"] .andes-badge--gray,\n[class^=\"seller-monitor\"] [class*=\"header\"] .andes-badge--gray,\n[class*=\" seller-monitor\"] [class*=\"header\"] .andes-badge--gray {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n}\n[class^=\"module-card\"] [class*=\"header\"] .andes-badge--gray--quiet,\n[class*=\" module-card\"] [class*=\"header\"] .andes-badge--gray--quiet,\n[class^=\"seller-monitor\"] [class*=\"header\"] .andes-badge--gray--quiet,\n[class*=\" seller-monitor\"] [class*=\"header\"] .andes-badge--gray--quiet {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ===== 91-home.css ===== */\n/* ===========================================================================\n   91-home.css — home-page \"ecosystem\" widgets\n   ===========================================================================\n\n   The landing page is built from yet another set of components, separate from\n   the `ui-*` search stack (60-search), the `poly-*` cards (20-cards) and the\n   `andes-landings-*` campaign shell (92-landings). Nothing in the earlier\n   passes matched any of the prefixes below, which is why they rendered as\n   dark-on-dark and white-on-dark patches:\n\n     advertising-square*              promo tile (also the white block that\n                                      appears to the right of the hero)\n     dynamic-access-card-ecosistemic* \"Medios de pago\", \"Menos de $40.000\",\n                                      \"Más vendidos\", \"Compra protegida\"\n     card-grid-anchor                 department grid titles\n     card-item__title                 carousel card titles\n     section-header(__title)          section headings\n     row-container(--white)           section shell marked \"white\"\n     loyalty-widget-v2*               loyalty / shipping banner\n     site-shopping-info               \"Paga con tarjeta o en efectivo\" strip\n\n   Every literal here was measured on the live home page: `rgba(0,0,0,.9)` for\n   titles and body, `rgb(255,255,255)` for the shells, `rgb(75,75,75)` for the\n   small promo caption.\n\n   Hard rule inherited from 92-landings.css: never widen a `[class*=\"…\"]`\n   substring so that it can swallow a content class. `advertising-square__info`\n   and `advertising-square` are both surfaces, but `…__image` / `…__thumbnail`\n   are media and stay untouched; selectors below name the exact classes.\n   =========================================================================== */\n\n/* ---- Section shells that are hard-coded white --------------------------- */\n.row-container,\n.row-container--white,\n.section-header,\n.site-shopping-info,\n.loyalty-widget-v2,\n.loyalty-widget-v2__body,\n.loyalty-widget-v2__body__coupon,\n.advertising-square {\n  background-color: transparent !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n\n/* The page itself carries the tone; these shells only need to stop painting\n   white over it. Where a shell genuinely needs a raised surface (the promo\n   tile), give it the card tone instead of transparency. */\n.advertising-square {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n.loyalty-widget-v2,\n.loyalty-widget-v2__body,\n.site-shopping-info {\n  background-color: var(--ml-surface-1, #181c22) !important;\n}\n\n/* ---- Headings ----------------------------------------------------------- */\n.section-header__title,\n.section-header h1,\n.section-header h2,\n.section-header h3,\n.section-header__link,\n.card-grid-anchor,\n.card-item__title {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* \"Mostrar todas las ofertas\" and friends sit next to the heading. */\n.section-header__link,\n.section-header a {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n\n/* ---- \"Ecosystem\" access cards (Medios de pago / Más vendidos / …) ------- */\n.dynamic-access-card-ecosistemic,\n.dynamic-access-card-ecosistemic__container,\n.dynamic-access-card-ecosistemic__body {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n.dynamic-access-card-ecosistemic__title {\n  color: var(--ml-text-primary, #e3e8ef) !important; /* was rgba(0,0,0,.9) */\n}\n.dynamic-access-card-ecosistemic__description {\n  color: var(--ml-text-secondary, #a9b3c1) !important; /* was rgba(0,0,0,.9) */\n}\n/* The card ships a blue CTA; it must keep its fill and its label. */\n.dynamic-access-card-ecosistemic a,\n.dynamic-access-card-ecosistemic button {\n  border-color: var(--ml-border, #2f3742) !important;\n}\n\n/* ---- Promo tile caption ------------------------------------------------- */\n/* `HASTA 40% OFF` is rgb(75,75,75) at 10px/600 — 1.6:1 on the dark tile. */\n.advertising-square__info,\n.advertising-square__info--title,\n.advertising-square__info--text {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.advertising-square__info--text {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n\n/* ---- Carousel cards inside the home sections ---------------------------- */\n/* `card-item__title` is the home carousel card; the product cards on listings\n   are `poly-*` and were already handled in 20-cards.css. */\n.card-item,\n.card-item__content,\n.card-item__body {\n  background-color: transparent !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.card-item__price,\n.card-item .andes-money-amount,\n.card-item .andes-money-amount__fraction {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* ---- Department grid ---------------------------------------------------- */\n.card-grid-anchor:hover {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n/* ---- \"Paga con tarjeta o en efectivo\" strip ------------------------------\n   Inside `.site-shopping-info` MELI renders `.info-slide` with a bare\n   `<h2>`, `<p>` and `<a>` — no classes at all — at rgb(75,75,75) and\n   rgba(0,0,0,.65). Class-based coverage can never reach them, so these\n   rules anchor on the container and go structural. */\n.site-shopping-info .info-slide h2,\n.site-shopping-info .info-slide h3,\n.site-shopping-info .info-slide strong,\n.site-shopping-info [class^=\"info-slide\"] :is(h2, h3, strong) {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.site-shopping-info .info-slide p,\n.site-shopping-info .info-slide span,\n.site-shopping-info .info-slide li,\n.site-shopping-info [class^=\"info-slide\"] :is(p, span, li) {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n.site-shopping-info .info-slide a,\n.site-shopping-info [class^=\"info-slide\"] a {\n  color: var(--ml-blue, #5b9bff) !important;\n}\n\n/* ---- Category block + back-navigation row ------------------------------- */\n/* `categories-new-design > row > wrapper` and `navigation > row container\n   history` are both plain `<div>` shells hard-coded white. */\n.categories-new-design,\n.categories-new-design .row,\n.categories-new-design .wrapper,\n[class^=\"categories-new\"],\n[class^=\"categories-new\"] .row,\n[class^=\"categories-new\"] .wrapper,\n.navigation .row,\n.navigation [class*=\"history\"],\n[class*=\"row\"][class*=\"container\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.navigation [class*=\"history\"] :is(h1, h2, h3, h4, span, p, a, div) {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* ---- Carousel page dots ------------------------------------------------- */\n/* The snapped carousel renders page markers as `<button>` pills painted #fff;\n   on a dark page they look like stray white commas. */\n.andes-carousel-snapped__container button,\n.andes-carousel-snapped button,\n[class^=\"andes-carousel-snapped\"] li > button {\n  background-color: var(--ml-border-strong, #3d4653) !important;\n  border-color: transparent !important;\n}\n.andes-carousel-snapped__container button[aria-selected=\"true\"],\n.andes-carousel-snapped button[aria-selected=\"true\"],\n[class^=\"andes-carousel-snapped\"] li > button[class*=\"active\"],\n[class^=\"andes-carousel-snapped\"] li > button[aria-current=\"true\"] {\n  background-color: var(--ml-blue, #5b9bff) !important;\n}\n\n/* ===== 92-landings.css ===== */\n/* ============================================================================\n   92-landings.css — MELI's campaign/landing page builder.\n   Measured on `mercadolibre.com.co/ofertas/supermercado`, which is built with a\n   THIRD component system on top of Andes:\n\n     sbc-*              \"Supermercado / store brand campaign\" shell\n     sbc-landing-*      landing layout\n     ui-sbc-main-*      landing content blocks\n     andes-landings-*   landing typography and blocks\n     products-gallery-* product rails inside a landing\n\n   Covering this family makes /ofertas, /ofertas/supermercado, Black Friday,\n   Cyber Monday, back-to-school and every other campaign page fall in line\n   without per-campaign rules.\n   ========================================================================== */\n\n/* ---- Landing shells ----------------------------------------------------\n   Scope note: `[class*=\"sbc-main-\"]` / `[class*=\"ui-sbc-main\"]` were removed\n   from this list. They matched `.ui-sbc-main-banner__overlay`, which is an\n   absolutely-positioned layer sitting on top of the hero photo — colouring it\n   hid the banner (see the long note further down). Page-level shells only. */\n.sbc-landing-layout,\n[class*=\"sbc-landing-layout\"],\n.sbc,\n[class*=\"sbc-container\"],\n[class*=\"sbc-section\"] {\n  background-color: var(--ml-surface-0) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* Campaign cards/rows inside a landing keep the raised surface. */\n[class*=\"sbc-landing\"] [class*=\"card\"],\n[class*=\"sbc-main\"] [class*=\"card\"],\n[class*=\"ui-sbc-main\"] [class*=\"card\"],\n[class*=\"sbc-section\"] [class*=\"card\"],\n[class*=\"sbc-container\"] [class*=\"card\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Landing typography ------------------------------------------------\n   MELI ships `andes-landings-typography` with a hard-coded rgb(26,26,26).\n   That single class is reused for every heading in every campaign page. */\n.andes-landings-typography,\n[class*=\"andes-landings-typography\"],\n[class*=\"andes-landings-title\"],\n[class*=\"andes-landings-subtitle\"],\n[class*=\"andes-landings-text\"] {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"andes-landings-typography--secondary\"],\n[class*=\"andes-landings-subtitle\"] {\n  color: var(--ml-text-secondary) !important;\n}\n[class*=\"andes-landings-link\"] {\n  color: var(--ml-blue) !important;\n}\n\n/* ---- Product rails inside a landing ------------------------------------ */\n[class*=\"products-gallery\"] {\n  background-color: transparent !important;\n}\n[class*=\"products-gallery__title\"],\n[class*=\"products-gallery\"] h2,\n[class*=\"products-gallery\"] h3 {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"products-gallery\"] [class*=\"subtitle\"],\n[class*=\"products-gallery\"] [class*=\"description\"] {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Landing buttons ---------------------------------------------------\n   Classless <button> elements appear inside the campaign rails; scope them by\n   the landing container so no global button styling is introduced. */\n[class*=\"sbc-landing\"] button,\n[class*=\"sbc-main\"] button,\n[class*=\"ui-sbc-main\"] button,\n[class*=\"andes-landings\"] button,\n[class*=\"products-gallery\"] button {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Campaign banners --------------------------------------------------\n   Campaign hero banners are images ON PURPOSE. Only the frame around them is\n   themed, so the promotional art keeps its own colours. */\n[class*=\"sbc-banner\"],\n[class*=\"sbc-hero\"],\n[class*=\"andes-landings-banner\"],\n[class*=\"andes-landings-hero\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n/* ---- Landing hero background ------------------------------------------\n   CRITICAL FINDING: `.andes-landings-background--hero` paints the campaign\n   hero with `linear-gradient(rgb(233,233,233) 40%, rgb(255,255,255) 100%)`.\n   A light GRADIENT has `background-color: transparent`, so neither a\n   computed-style audit nor a `background-color` override will ever see it —\n   this block looked correct to the probe while being the brightest area on\n   the screen. Gradients must be killed with `background-image: none`.\n\n   DANGER — DO NOT WIDEN THESE SELECTORS. `[class*=\"andes-landings-background\"]`\n   matches not only the decorative backdrop but ALSO the three content classes\n   that carry real campaign imagery and sit ABOVE it at `z-index: 1`:\n     .andes-landings-background-container          (the image frame)\n     .andes-landings-background-carousel-item      (the slide)\n     .andes-landings-image-container               (the <img> wrapper)\n   Painting those made every hero banner a solid colour block with the photo\n   hidden underneath — the \"carousel disappeared\" bug. Same for\n   `[class*=\"ui-sbc-main\"]`, which matched `.ui-sbc-main-banner__overlay`\n   (absolutely positioned over the photo).\n\n   Rule of thumb: this family gets `background-image: none` ONLY. Never a\n   background-color, and never through a substring selector wide enough to\n   swallow `-image-container` / `__overlay`. */\n.andes-landings-background,\n[class*=\"andes-landings-background--\"] {\n  background-image: none !important;\n}\n/* Keep a hint of the campaign glow, but dark: a vertical wash from a slightly\n   raised tone to the page tone reads as depth without glare. */\n[class*=\"andes-landings-background--hero\"] {\n  background-image: linear-gradient(\n    var(--ml-surface-1) 0%,\n    var(--ml-surface-0) 70%\n  ) !important;\n}\n[class*=\"andes-landings-background--section\"],\n[class*=\"andes-landings-background--card\"] {\n  background-image: none !important;\n  background-color: var(--ml-surface-1) !important;\n}\n\n/* Campaign imagery must never be tinted or covered by us: these are photos and\n   promotional art. Declared after the backdrop rules so they win any tie. */\n[class*=\"andes-landings-image-container\"],\n[class*=\"andes-landings-background-container\"],\n.andes-landings-background-carousel-item,\n[class*=\"andes-landings-background-carousel-item\"],\n[class*=\"ui-sbc-main-banner__overlay\"] {\n  background-color: transparent !important;\n  background-image: none !important;\n}\n[class*=\"andes-landings-image-container\"] img,\n[class*=\"andes-landings-background-carousel-item\"] img,\n[class*=\"ui-sbc-main-banner\"] img {\n  opacity: 1 !important;\n  visibility: visible !important;\n}\n\n/* Category thumbnails that sit on that hero gradient. */\n.sbc-thumbnails-carousel,\n[class*=\"sbc-thumbnails\"] {\n  background-color: transparent !important;\n}\n[class*=\"sbc-thumbnails\"] [class*=\"__item\"] {\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Campaign landing shell: bare-word classes --------------------------\n   `/ofertas` is built with yet another vocabulary, and its classes are single\n   lowercase words with no prefix at all: `header_title`, `header_subtitle`,\n   `results-quantity`, `selectors_header_container`. Nothing in the theme\n   matched them, so the page title and the result counter kept MELI's `#333`\n   (1.6:1 on the dark page).\n\n   They are also easy to mistake for generic names, so each one is written out\n   in full rather than derived from a prefix pattern. */\n.header_title,\n.header_subtitle,\n.results-quantity,\n.selectors_header_container,\n[class=\"header_title\"],\n[class=\"header_subtitle\"],\n[class=\"results-quantity\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.header_subtitle,\n.results-quantity {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n  -webkit-text-fill-color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n.selectors_header_container {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle, #242a33) !important;\n}\n\n/* Variation labels on the offer cards (\"Talla M\", \"Color negro\"), which are\n   rgba(0,0,0,.55) and sit inside the poly-* card system. */\n.poly-component__variations-text,\n[class*=\"poly-component__variations\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n  -webkit-text-fill-color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n\n/* ---- Category index (/categorias) --------------------------------------\n   Yet another prefix-free vocabulary: `categories__*` and\n   `categories-container__*`. Measured literals on the real page:\n     .categories__title-link          rgb(51,51,51)      32 nodes\n     .categories__subtitle-title      rgba(0,0,0,.45)   437 nodes\n     .categories-container__title     rgb(74,74,74)\n   437 is the largest single count seen anywhere in this theme, so the page was\n   almost entirely unreadable while every other rule applied normally.\n\n   Both properties are set: this page also paints with fill-color, and `color`\n   alone leaves the glyphs dark. */\n.categories__title-link,\n.categories-container__title,\n[class*=\"categories__title\"],\n[class*=\"categories-container__title\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.categories__subtitle-title,\n[class*=\"categories__subtitle\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n  -webkit-text-fill-color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n.categories__title-link:hover,\n[class*=\"categories__title\"]:hover {\n  color: var(--ml-blue, #5b9bff) !important;\n  -webkit-text-fill-color: var(--ml-blue, #5b9bff) !important;\n}\n[class*=\"categories\"] a,\n[class*=\"categories\"] a * {\n  color: inherit;\n}\n\n/* ===== 93-styled-components.css ===== */\n/* ============================================================================\n   93-styled-components.css — pages built with styled-components\n   (`myaccount.mercadolibre.com.co/my_purchases`, `.../favorites`, account\n   settings, and other newer \"My Meli\" surfaces).\n\n   THE PROBLEM: these pages emit hashed class names, e.g.\n     styles__Paragraph-sc-14jk16e-0 bUzBAV\n     sc-gsMGyr hztILC\n   The `sc-<hash>` segment and the trailing hash CHANGE ON EVERY DEPLOY. Any\n   rule that names them is dead on the next build.\n\n   THE STABLE PART is the component name in the `styles__<Name>-sc-<hash>`\n   prefix — \"Paragraph\", \"Button\", \"Card\", \"Page\" — because it comes from the\n   developer's styled(Component) call, not from the build hash. Selectors below\n   only ever use `[class*=\"styles__<Name>\"]`, which survives redeploys.\n\n   Measured component bases on /my_purchases:\n     Wrapper 170 · Button 65 · Paragraph 35 · Image 21 · ListItem 19\n     ListItemChildren 19 · ChildrenWrapper 19 · Thumbnail 6 · Typography 3\n     List 3 · Page 1 · Card 1 · SearchBox 1 · FloatingMenu 1\n   Only `Paragraph` carried dark text (30 nodes, both .9 and .55 alpha).\n   ========================================================================== */\n\n/* ---- Text ---------------------------------------------------------------\n   Every Paragraph variant is dark, so default them all to primary. Hierarchy\n   flattens a little, but legibility wins; per-variant refinement would require\n   the hashes and is not worth the fragility. */\n[class*=\"styles__Paragraph\"],\n[class*=\"styles__Typography\"],\n[class*=\"styles__ListItemChildren\"],\n[class*=\"styles__ChildrenWrapper\"],\n[class*=\"styles__CardContent\"],\n[class*=\"styles__AdvertisingContent\"] {\n  color: var(--ml-text-primary) !important;\n}\n\n/* Links and muted meta keep their distinction through the semantic wrappers\n   rather than the hashed class. */\n[class*=\"styles__Paragraph\"] a,\n[class*=\"styles__Paragraph\"] strong a {\n  color: var(--ml-blue) !important;\n}\n[class*=\"styles__ListItem\"] [class*=\"styles__Paragraph\"]:last-child {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Surfaces ---------------------------------------------------------- */\n[class*=\"styles__Page\"],\n[class*=\"styles__FloxPageStyle\"],\n[class*=\"styles__Card\"]:not([class*=\"styles__CardContent\"]),\n[class*=\"styles__ContentWrapper\"],\n[class*=\"styles__SearchBoxWrapper\"] {\n  background-color: var(--ml-surface-0) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n/* `styles__Wrapper` is the single most generic styled-component name MELI\n   ships: it is used BOTH for page layout containers AND for the hover/overlay\n   layers stacked on top of a product photo. Painting it opaque was a defect\n   with a very confusing symptom:\n\n     gamut inspection of one 80x80 thumbnail on /my_purchases/list showed\n     TWO div.styles__Wrapper elements ABOVE the <img> in the hit-test stack,\n     each with background rgb(18,21,26) — my --ml-surface-0 — so the photo was\n     rendered and simply covered by two opaque rectangles.\n\n   `elementsFromPoint` is what exposed it; getComputedStyle on the <img> looked\n   perfectly healthy (naturalWidth 200, opacity 1, filter none, 80x80 box).\n\n   A generic wrapper must inherit, never paint. The page surface underneath is\n   already dark, so transparent wrappers give the same look without ever\n   covering content. */\n[class*=\"styles__Wrapper\"] {\n  background-color: transparent !important;\n  background-image: none !important;\n}\n[class*=\"styles__Card\"]:not([class*=\"styles__CardContent\"]),\n[class*=\"styles__ListItem\"],\n[class*=\"styles__ChildrenWrapper\"] {\n  background-color: var(--ml-surface-1) !important;\n}\n[class*=\"styles__ListItem\"]:hover {\n  background-color: var(--ml-surface-2) !important;\n}\n\n/* ---- Buttons ----------------------------------------------------------- */\n[class*=\"styles__Button\"] {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"styles__Button\"]:hover {\n  background-color: var(--ml-surface-3) !important;\n}\n/* A primary/loud styled button keeps the brand blue. */\n[class*=\"styles__Button\"][class*=\"__primary\"],\n[class*=\"styles__Button\"][class*=\"--primary\"],\n[class*=\"styles__Button\"][class*=\"loud\"] {\n  background-color: var(--ml-blue-fill) !important;\n  color: var(--ml-text-on-brand) !important;\n}\n\n/* ---- Search box, date picker and floating menu ------------------------- */\n[class*=\"styles__SearchBox\"],\n[class*=\"styles__MenuDatePicker\"],\n[class*=\"styles__FloatingMenu\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"styles__FloatingMenu\"] {\n  background-color: var(--ml-surface-3) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n[class*=\"styles__IconContainer\"] {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n/* `styles__Thumbnail` is the product letterbox on /my_purchases: its colour is\n   owned by --ml-thumb-plate (98-late-fixes.css), because a dark band around a\n   white-background product photo makes the photo disappear. */\n[class*=\"styles__Thumbnail\"] {\n  border-color: var(--ml-border) !important;\n}\n\n/* ---- Advertising blocks inside the purchase list ----------------------- */\n[class*=\"styles__AdvertisingContainer\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n/* ---- Raw styled() wrappers without a `styles__` name -------------------\n   Some wrappers are plain `styled.div` calls, so their class is ONLY\n   `sc-<hash> <hash>` with no component name at all — there is nothing stable\n   to hook. This is the one place where a structural attribute is the reliable\n   anchor: the search wrapper carries `role=\"search\"`. */\n[role=\"search\"],\ndiv[role=\"search\"] {\n  background-color: var(--ml-surface-1) !important;\n  color: var(--ml-text-primary) !important;\n}\n/* Andes search-box control on those pages. */\n.andes-form-control--search-box,\n[class*=\"andes-form-control--search-box\"] {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ===== 94-support.css ===== */\n/* ============================================================================\n   94-support.css — Consumer Support / \"Mi Meli\" pages\n   (/preguntas/, /ayuda/, /inbox/, /vender/ and their help flows).\n\n   NOTE: glob-looking route patterns are deliberately written WITHOUT the\n   asterisk, because a slash followed by an asterisk opens a nested CSS\n   comment and silently leaves an unterminated block behind (four of them here,\n   detected as a 416-vs-412 comment imbalance in the built file).\n\n   Fourth component system, measured on `/preguntas/comprador`:\n     sc-*        support centre widgets (question cards, labels, toggles)\n     myml-*      \"Mi Meli\" side navigation\n     inbox-*     purchase inbox / messages\n     app-wrapper the shell those pages mount into\n\n   These pages ship their own labels with `rgb(0,0,0)` / `rgba(0,0,0,.55)`\n   literals and their own white cards, so they need their own pass.\n   ========================================================================== */\n\n/* ---- Page shells -------------------------------------------------------- */\n.app-wrapper,\n#app-wrapper,\n[class*=\"app-wrapper\"],\n.myml-nav,\n[class*=\"myml-nav\"],\n.inbox-sidebar,\n.inbox-sidebar__content,\n[class*=\"inbox-sidebar\"],\n[class*=\"sc-container\"],\n[class*=\"sc-main\"] {\n  background-color: var(--ml-surface-0) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* Cards and panels inside the support centre. */\n[class*=\"sc-card\"],\n[class*=\"sc-panel\"],\n[class*=\"sc-section\"],\n[class*=\"sc-container\"] [class*=\"card\"],\n[class*=\"myml-nav\"] [class*=\"card\"],\n[class*=\"inbox\"] [class*=\"card\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- mi meli side navigation ------------------------------------------- */\n.myml-nav__section-title,\n[class*=\"myml-nav__section-title\"] {\n  color: var(--ml-text-secondary) !important;\n  text-transform: none;\n}\n.myml-nav__menu-item-text,\n[class*=\"myml-nav__menu-item-text\"],\n[class*=\"myml-nav__menu-item\"] a,\n[class*=\"myml-nav\"] li a {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"myml-nav__menu-item\"]:hover,\n[class*=\"myml-nav__menu-item\"] a:hover {\n  color: var(--ml-blue) !important;\n}\n[class*=\"myml-nav__menu-item\"][class*=\"--active\"],\n[class*=\"myml-nav__menu-item\"][class*=\"--selected\"] {\n  background-color: var(--ml-blue-tint) !important;\n  color: var(--ml-blue) !important;\n}\n[class*=\"myml-nav\"] [class*=\"divider\"] {\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Support centre labels and question cards -------------------------- */\n.sc-label__text,\n[class*=\"sc-label__text\"],\n[class*=\"sc-label__text_link\"],\n[class*=\"sc-label__text_detail\"],\n[class*=\"sc-label__date\"],\n[class*=\"sc-label__title\"] {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sc-label__text_detail\"],\n[class*=\"sc-label__date\"],\n[class*=\"sc-label__subtext\"] {\n  color: var(--ml-text-muted) !important;\n}\n[class*=\"sc-label__text_link\"] {\n  color: var(--ml-blue) !important;\n}\n\n/* Question rows (\"question desktop\" is measured markup, not a typo). */\n[class*=\"sc-question\"],\n.question.desktop,\n[class*=\"question desktop\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sc-question\"] [class*=\"subLabel\"],\n[class*=\"sc-question\"] [class*=\"sublabel\"],\n[class*=\"sc-question\"] [class*=\"sub-label\"] {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* Accordion toggles: the open state is painted white in the light theme. */\n[class*=\"sc-question--toggle\"],\n[class*=\"sc-question-toggle\"],\n[class*=\"sc-toggle\"] {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sc-question--toggle\"].opened,\n[class*=\"sc-question--toggle\"][class*=\"--opened\"],\n[class*=\"sc-question--toggle\"][aria-expanded=\"true\"] {\n  background-color: var(--ml-surface-3) !important;\n}\n\n/* Answer bodies and help copy. */\n[class*=\"sc-answer\"],\n[class*=\"sc-help\"],\n[class*=\"sc-description\"],\n[class*=\"sc-content\"] p,\n[class*=\"sc-content\"] li {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sc-answer\"] a,\n[class*=\"sc-help\"] a {\n  color: var(--ml-blue) !important;\n}\n\n/* ---- Misc leftovers ---------------------------------------------------- */\n/* The breadcrumb has a `__label` variant beyond `__link`/`__title`. */\n.andes-breadcrumb__label,\n[class*=\"andes-breadcrumb\"] [class*=\"__label\"] {\n  color: var(--ml-text-secondary) !important;\n}\n/* Pagination numbers on these pages are links, not buttons. */\n.andes-pagination__link {\n  background-color: transparent !important;\n}\n[class*=\"sc-\"] [class*=\"empty\"],\n[class*=\"sc-\"] [class*=\"no-results\"] {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ===== 95-misc.css ===== */\n/* ============================================================================\n   95-misc.css — everything that does not belong to a page: Meli Ads units,\n   promo pills, shortcut hints, the leftover andes-* primitives (toast,\n   progress, spinner, tooltip wrapper, carousel dots) and the tags MELI's own\n   design system paints white with no page context.\n\n   HARD RULE for this file: `.polylabel-fw-*` and `.polylabel-fs-*` are\n   font-weight / font-size utilities, NOT colour classes. Setting colour on\n   them breaks typography everywhere. Only `.polylabel-*` *pill* variants are\n   coloured here.\n\n   Ads and product imagery are never dimmed, filtered or opacitied in this\n   file: dimming belongs to --ml-img-dim in base.css (S3).\n\n   Already dark elsewhere — intentionally not repeated here:\n     .bads-vertical-product-card__image-container .......... 50-coverage.css\n     .bads-vertical-product-card__title/price/subtitle ..... 30-text.css\n     .bads-adaptive-carousel__arrow ........................ 50-coverage.css\n     .andes-tooltip*, .andes-modal*, .andes-snackbar*,\n       .andes-toast (surface + text) ....................... 40-forms.css\n     .shortcut-key (surface) ............................... 10-header.css\n     .modeless-box* surfaces ............................... 20-cards.css\n     .poly-variations-compacted__circle .................... 20-cards.css\n     .ui-label-builder text ................................ 30-text.css\n   `.image-option` / `.image-option-select`, `.andes-progress*`,\n   `.andes-spinner*` and `.andes-carousel-snapped__dot` are styled nowhere else,\n   so this file owns them completely.\n   ========================================================================== */\n\n/* ---- Meli Ads -----------------------------------------------------------\n   `.bads-vertical-product-card` is a real ad card: keep it as a distinct\n   panel so it reads as an ad, never as organic content. The photo inside is\n   untouched (only --ml-img-dim applies).\n   The family reset sets NO background and NO colour on purpose: 50-coverage.css\n   already paints `.bads-vertical-product-card__image-container`\n   (--ml-surface-2) and `.bads-adaptive-carousel__arrow` (--ml-surface-3), and\n   30-text.css already owns the card's title / price / subtitle colours. A\n   blanket background/colour here would win on equal specificity simply by\n   being later in the bundle and wipe both. */\n[class^=\"bads-\"],\n[class*=\" bads-\"] {\n  border-color: var(--ml-border-subtle) !important;\n}\n.bads-vertical-product-card {\n  background-color: var(--ml-surface-1) !important;\n  border: 1px solid var(--ml-border-subtle) !important;\n}\n/* The image well keeps a recessed surface so white studio shots do not glare.\n   `.bads-vertical-product-card__image-container` itself is already painted in\n   50-coverage.css; only the unmeasured `*image*` siblings are caught here. */\n[class^=\"bads-\"][class*=\"image\"]:not(.bads-vertical-product-card__image-container),\n[class*=\" bads-\"][class*=\"image\"]:not(.bads-vertical-product-card__image-container) {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n/* Adaptive carousel rail: transparent so it sits on whatever page hosts it. */\n.bads-adaptive-carousel,\n[class^=\"bads-adaptive-carousel\"],\n[class*=\" bads-adaptive-carousel\"] {\n  background-color: transparent !important;\n}\n/* Carousel navigation arrows (the base rule is in 50-coverage.css). Hover\n   raises them to the top layer; disabled drops one layer AND keeps\n   --ml-text-secondary (7.35:1 on surface-2) rather than --ml-text-muted, so the\n   only difference is depth + a weaker border, never a sub-4.5:1 label. */\n.bads-adaptive-carousel__arrow:hover {\n  background-color: var(--ml-surface-4) !important;\n  border-color: var(--ml-border-strong) !important;\n  color: var(--ml-text-primary) !important;\n}\n.bads-adaptive-carousel__arrow--disabled {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-secondary) !important;\n}\n/* \"Publicidad\" / sponsored micro-label under the unit. */\n[class^=\"bads-\"][class*=\"label\"],\n[class*=\" bads-\"][class*=\"label\"],\n.bads-vertical-product-card__ads-promotions {\n  color: var(--ml-text-muted) !important;\n}\n\n/* ---- Promo pills (`polylabel-*`) --------------------------------------\n   ONLY the pill variants. `.polylabel-fw-*`/`.polylabel-fs-*` are excluded on\n   purpose and must stay untouched.\n   `.polylabel-pill` already gets the brand green fill + off-white text from\n   40-forms.css. Every variant below therefore restates BOTH its surface and\n   its text, otherwise a `color`-only override would put green text on a green\n   fill, or pink text on a green fill. */\n.polylabel-pill {\n  border-color: var(--ml-border-subtle) !important;\n}\n/* Discount / \"-25%\" pill: tinted green surface, lightened green text. */\n.polylabel-pill--discount,\n.polylabel-price--discount,\n[class*=\"polylabel-pill\"][class*=\"discount\"] {\n  background-color: var(--ml-green-tint) !important;\n  color: var(--ml-green) !important;\n}\n/* Promo / campaign pill, pink surface on light. */\n.polylabel-pill--promo,\n.polylabel-pill--offer,\n[class*=\"polylabel-pill\"][class*=\"promo\"] {\n  background-color: var(--ml-pink-tint) !important;\n  color: var(--ml-pink) !important;\n}\n/* Scarcity / last-units pill, peach surface on light. */\n.polylabel-pill--scarcity,\n[class*=\"polylabel-pill\"][class*=\"scarcity\"] {\n  background-color: var(--ml-peach-tint) !important;\n  color: var(--ml-orange) !important;\n}\n\n/* ---- Swatch / option tiles ---------------------------------------------\n   `.image-option` and `.image-option-select` are the white-bordered pickers\n   (colour/photo variants). Surface for `.image-option` is 20-cards.css. */\n.image-option,\n.image-option-select {\n  border-color: var(--ml-border) !important;\n}\n.image-option:hover,\n.image-option-select:hover {\n  border-color: var(--ml-border-strong) !important;\n}\n.image-option--selected,\n.image-option-select--selected,\n.image-option[aria-checked=\"true\"],\n.image-option-select[aria-checked=\"true\"] {\n  border-color: var(--ml-blue) !important;\n  background-color: var(--ml-surface-2) !important;\n}\n\n/* ---- Keyboard shortcut hints ------------------------------------------\n   Surface + text are in 10-header.css / 30-text.css; the inner `<kbd>` and the\n   divider between hint fragments are not. */\n.shortcut-key kbd,\n.shortcut-key__key {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border-strong) !important;\n}\n/* The separator sits on the --ml-surface-2 key chip (10-header.css);\n   --ml-text-secondary is used instead of --ml-text-muted, which only reaches\n   4.27:1 against that surface. */\n.shortcut-key__separator {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Modeless boxes ---------------------------------------------------\n   Surfaces are 20-cards.css (`.modeless-box`, `.modeless-box-scroll-rail`) and\n   the header text colour is 50-coverage.css; neither is restated here. What is\n   left is the header/footer band edges and the close affordance. */\n.modeless-box-header,\n.modeless-box-footer {\n  background-color: transparent !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.modeless-box__close,\n.modeless-box-close {\n  color: var(--ml-text-secondary) !important;\n}\n.modeless-box__close:hover,\n.modeless-box-close:hover {\n  background-color: var(--ml-surface-4) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Andes tooltip / modal / snackbar / toast -------------------------\n   All surfaces are dark from 40-forms.css. Only the pieces that file does not\n   name are here: tooltip arrow, modal header border, snackbar action link. */\n.andes-tooltip__arrow,\n.andes-tooltip__arrow::before {\n  background-color: var(--ml-surface-4) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-modal__header,\n.andes-dialog__header {\n  border-bottom: 1px solid var(--ml-border-subtle) !important;\n}\n.andes-modal__footer,\n.andes-dialog__footer {\n  border-top: 1px solid var(--ml-border-subtle) !important;\n}\n.andes-snackbar__action,\n.andes-toast__action {\n  color: var(--ml-blue) !important;\n}\n.andes-snackbar__close,\n.andes-toast__close {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Carousel dots ---------------------------------------------------- */\n.andes-carousel-snapped__dot {\n  background-color: var(--ml-border-strong) !important;\n  border-color: transparent !important;\n}\n.andes-carousel-snapped__dot--active,\n.andes-carousel-snapped__dot[aria-current=\"true\"] {\n  background-color: var(--ml-blue) !important;\n}\n\n/* ---- Progress / spinner ----------------------------------------------- */\n.andes-progress {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.andes-progress__bar,\n.andes-progress__value,\n.andes-progress-bar {\n  background-color: var(--ml-blue-fill) !important;\n}\n.andes-progress-container,\n.andes-progress-track {\n  background-color: var(--ml-surface-3) !important;\n}\n.andes-spinner,\n.andes-spinner__icon {\n  color: var(--ml-blue) !important;\n}\n.andes-spinner__circle,\n.andes-spinner__ring {\n  border-color: var(--ml-border-strong) !important;\n  border-top-color: var(--ml-blue) !important;\n}\n\n/* ---- Misc leftovers --------------------------------------------------- */\n.ui-label-builder {\n  background-color: transparent !important;\n}\n.poly-variations-compacted__circle--selected,\n.poly-variations-compacted__circle[aria-checked=\"true\"] {\n  border-color: var(--ml-blue) !important;\n  box-shadow: 0 0 0 1px var(--ml-blue) !important;\n}\n/* ---- Coupons page (/cupones) -------------------------------------------\n   The coupon card is its own small vocabulary with NO prefix at all, so\n   nothing in this theme matched it:\n\n     .coupon-card\n       .top-row                        --ml-green-tint (dark since my remap)\n         .text-label                   rgba(0,0,0,.55)   393 nodes\n         .subtitles                     already fixed by generic rules\n       .die-cut                        rgb(255,255,255)  102 nodes\n       .bottom-row.expiration-date      --ml-green-tint\n         .expiration-text              rgba(0,0,0,.55)    78 nodes\n\n   Two distinct defects:\n     1. MELI's black 55% text sits on MY dark green band, not on white, so it\n        is invisible. The tidied text must go light now that the band is dark.\n     2. `.die-cut` is the perforated separator strip painted pure white — the\n        white line cutting each card in half on the user's screenshot.\n\n   Counts came from the probe at 753 problems on this one page, the second\n   largest single-page figure measured for this theme. */\n.coupon-card .text-label,\n.coupon-card .subtitles,\n.coupon-card .expiration-text,\n.coupon-card .top-row,\n.coupon-card .bottom-row,\n.coupon-card span:not([class]),\n.coupon-card p {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* Secondary lines (the \"Compra minima / Tope de\" wording) sit one step down\n   so the headline amount still leads the eye. */\n.coupon-card .text-label,\n.coupon-card .expiration-text {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n  -webkit-text-fill-color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n\n/* The perforated strip: was pure white, must be the dark band. A dashed\n   border keeps the \"tear here\" affordance after the white is gone. */\n.coupon-card .die-cut,\n[class*=\"coupon-card\"] .die-cut {\n  background-color: var(--ml-green-tint, #14261d) !important;\n  background-image: none !important;\n  border-color: var(--ml-border, #242a33) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n.coupon-card .die-cut > *,\n[class*=\"coupon-card\"] .die-cut * {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* The big \"10% OFF\" / \"$ 50.000 OFF\" amount is the card's anchor and MELI\n   paints it green; on a dark green band the green needs more luminance. */\n.coupon-card [class*=\"title\"],\n.coupon-card strong,\n.coupon-card b {\n  color: var(--ml-green, #34d17a) !important;\n  -webkit-text-fill-color: var(--ml-green, #34d17a) !important;\n}\n\n/* Screen-reader-only nodes are reported by the probe but paint nothing. */\n.coupon-card .sr-only,\n.sr-only {\n  color: transparent !important;\n  -webkit-text-fill-color: transparent !important;\n}\n\n/* ---- Purchase history (/gz/home/navigation) ----------------------------\n   Fifth namespace that never had a pass of its own: `ui-navigation-*`.\n\n     ui-navigation-month-label                         52 nodes\n     ui-navigation-component-list__item(.__month-label) 49 nodes\n     ui-navigation-header__lgpd__title / __content\n     ui-navigation__collapsible* , ui-navigation-icon\n\n   Measured defects on the live page:\n\n     .ui-navigation-month-label            rgba(0,0,0,.55)  \"Noviembre\"\n     .ui-navigation-header__lgpd__title    rgba(0,0,0,.9)   \"Tu historial\"\n     .ui-navigation-header__lgpd__content  a light surface\n\n   The per-item status line (\"Publicación finalizada\", \"Compra cancelada\",\n   \"Vencida\") reuses `ui-navigation-component-list__item` and inherits the same\n   light-theme black, which is the reported \"esa font quedó negra y casi no se\n   lee\". Both properties are set because this page also has fill-color cases. */\n[class*=\"ui-navigation-month-label\"],\n[class*=\"ui-navigation-component-list__item\"],\n[class*=\"ui-navigation-header__lgpd__title\"],\n[class*=\"ui-navigation__collapsible\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n/* Month labels are a header, so they stay one step softer than item titles. */\n[class*=\"ui-navigation-month-label\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n  -webkit-text-fill-color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n/* Any descendant that MELI painted black inside a history row. */\n[class*=\"ui-navigation-component-list__item\"] *,\n[class*=\"ui-navigation__collapsible\"] * {\n  color: inherit !important;\n  -webkit-text-fill-color: inherit !important;\n}\n/* The LGPD notice is a light card with a dark title. */\n[class*=\"ui-navigation-header__lgpd\"],\n[class*=\"ui-navigation-header__lgpd__content\"],\n[class*=\"ui-navigation-header__lgpd__switch-wrapper\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  background-image: none !important;\n  border-color: var(--ml-border, #242a33) !important;\n}\n[class*=\"ui-navigation__container\"],\n[class*=\"ui-navigation-v2\"],\n[class*=\"ui-navigation__collapsible-content\"] {\n  background-color: transparent !important;\n  background-image: none !important;\n}\n/* Status punctuation stays meaningful: cancelled/expired uses the danger tone,\n   finished uses the muted tone. Matching is on the visible word, which is the\n   only stable hook these rows offer. */\n[class*=\"ui-navigation-component-list__item\"] [class*=\"status\"],\n[class*=\"ui-navigation-component-list__item\"] [class*=\"state\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n  -webkit-text-fill-color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n\n/* ===== 96-nav-extras.css ===== */\n/* ============================================================================\n   96-nav-extras.css — shared navigation and footer components that only\n   surface on logged-in / seller pages.\n\n   Measured on the seller hub, but these are NOT seller-dashboard widgets: they\n   are the global header, footer and favourites bar, so they appear across the\n   whole site and belong to the theme regardless of the seller hub work.\n   ========================================================================== */\n\n/* ---- Footer navigation link columns ------------------------------------ */\n.nav-footer-navigation__link,\n.nav-footer-navigation__title,\n.nav-footer-hp,\n[class*=\"nav-footer-navigation\"] a,\n[class*=\"nav-footer-navigation\"] span {\n  color: var(--ml-text-secondary) !important;\n}\n.nav-footer-navigation__link:hover,\n[class*=\"nav-footer-navigation\"] a:hover {\n  color: var(--ml-blue) !important;\n}\n\n/* ---- Favourites bar (bottom bar on /favoritos and PDPs) ---------------- */\n.nav-favorites-bar,\n[class*=\"nav-favorites-bar\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n.nav-favorites-bar__chip-text,\n.nav-favorites-bar__buy-at-meli,\n[class*=\"nav-favorites-bar__chip\"] {\n  color: var(--ml-text-primary) !important;\n}\n.nav-favorites-bar__chip,\n[class*=\"nav-favorites-bar__chip\"]:not([class*=\"text\"]) {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n.nav-favorites-bar__tooltip,\n[class*=\"nav-favorites-bar__tooltip\"] {\n  background-color: var(--ml-surface-4) !important;\n  color: var(--ml-text-primary) !important;\n  border-color: var(--ml-border) !important;\n  box-shadow: var(--ml-shadow-pop) !important;\n}\n\n/* ---- Language switcher inside the user menu ---------------------------- */\n.nav-user-menu-language-switcher__section,\n[class*=\"nav-user-menu-language-switcher__section\"] {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n}\n.nav-user-menu-language-switcher__label,\n.nav-user-menu-language-switcher__value,\n.nav-user-menu-language-switcher__option-title,\n[class*=\"nav-user-menu-language-switcher\"] {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"nav-user-menu-language-switcher__option\"]:hover {\n  background-color: var(--ml-surface-4) !important;\n}\n\n/* ---- Seller-only header affordances ------------------------------------ */\n.nav-sellers-logo-label,\n.nav-header-sellers-action,\n.nav-seller-assistant__text,\n[class*=\"nav-sellers-logo-label\"],\n[class*=\"nav-header-sellers-action\"],\n[class*=\"nav-seller-assistant\"] {\n  color: var(--ml-text-primary) !important;\n}\n.nav-header-sellers-help__tail,\n.nav-header-sellers-help__options,\n[class*=\"nav-header-sellers-help\"] {\n  background-color: var(--ml-surface-3) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Side navigation shell --------------------------------------------- */\n.nav-sidebar,\n[class*=\"nav-sidebar\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Andes segmented control (design-system primitive) -----------------\n   Used by language switchers, view switchers and seller filters. The light\n   theme paints the track #fff and the selection #fff, which is invisible on\n   dark and looks like a missing control. */\n.andes-segmented-control,\n.andes-segmented-control__container {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n.andes-segmented-control__segment,\n[class*=\"andes-segment\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n}\n.andes-segmented-control__segment:hover,\n[class*=\"andes-segment\"]:hover {\n  background-color: var(--ml-surface-3) !important;\n  color: var(--ml-text-primary) !important;\n}\n.andes-segmented-control__selection {\n  background-color: var(--ml-surface-4) !important;\n  box-shadow: var(--ml-shadow-card) !important;\n}\n.andes-segmented-control__segment[class*=\"--active\"],\n.andes-segmented-control__segment[aria-checked=\"true\"],\n[class*=\"andes-segment\"][class*=\"--active\"] {\n  background-color: var(--ml-blue-tint) !important;\n  color: var(--ml-blue) !important;\n}\n\n/* ===== 97-seller.css ===== */\n/* ============================================================================\n   97-seller.css — MercadoLibre Seller Centre (`vendedores.mercadolibre.com.co`)\n\n   The seller hub is its own application with a THIRD look: a lavender canvas,\n   `sll-*` (seller listing) grid tables, `sc-*` chrome (header listing, task\n   cards, massive-actions toolbar, hover buttons, stacked scroll wrappers).\n   It shares the global header/footer (already covered in 96-nav-extras.css)\n   but nothing else, so it gets its own pass.\n\n   Measured on /publicaciones: 28 light grid rows + 7 light wrappers + 5 dark\n   labels. The grid row is the whole table body, so getting it right fixes\n   most of the page.\n   ========================================================================== */\n\n/* ---- Canvas and shells ------------------------------------------------- */\n.sll-layout,\n[class*=\"sll-layout\"],\n[class*=\"sll-main\"],\n[class*=\"seller-hub\"],\n[class*=\"sellers-hub\"],\n[class*=\"sc-page\"] {\n  background-color: var(--ml-surface-0) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Listing header ---------------------------------------------------- */\n.sc-header-listing__background,\n[class*=\"sc-header-listing__background\"] {\n  background-color: var(--ml-surface-0) !important;\n  background-image: none !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n.sc-header-listing__title,\n[class*=\"sc-header-listing__title\"] {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sc-header-listing\"] [class*=\"__subtitle\"],\n[class*=\"sc-header-listing\"] p {\n  color: var(--ml-text-secondary) !important;\n}\n\n/* ---- Listing grid ------------------------------------------------------\n   The 28 light rows are the publication table. Rows alternate meaning through\n   modifiers: `--item` is a product row, `--catalog` / `--family` are group\n   headers, so they get a raised / deeper tone to keep the hierarchy readable. */\n.sll-list-grid-row,\n[class*=\"sll-list-grid-row\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n.sll-list-grid-row--item,\n[class*=\"sll-list-grid-row--item\"] {\n  background-color: var(--ml-surface-1) !important;\n}\n.sll-list-grid-row--catalog,\n[class*=\"sll-list-grid-row--catalog\"],\n.sll-list-grid-row--family,\n[class*=\"sll-list-grid-row--family\"],\n.sll-list-grid-row--header,\n[class*=\"sll-list-grid-row--header\"] {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-secondary) !important;\n}\n[class*=\"sll-list-grid-row\"]:hover {\n  background-color: var(--ml-surface-2) !important;\n}\n/* Column header row of the same grid. */\n[class*=\"sll-list-grid\"] [class*=\"__header\"],\n[class*=\"sll-list-grid-header\"] {\n  background-color: var(--ml-surface-2) !important;\n  color: var(--ml-text-secondary) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* ---- Stacked / scroll wrappers ---------------------------------------- */\n.sll-list-grid-row__stacked,\n.sc-scroll-stacked,\n.sc-scroll-stacked__content-wrapper,\n[class*=\"sc-scroll-stacked\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n\n/* ---- Task cards and toolbars ------------------------------------------ */\n.andes-card.sc-task-card,\n.sc-task-card,\n[class*=\"sc-task-card\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sc-massive-actions-toolbar\"] {\n  background-color: var(--ml-surface-1) !important;\n  border-color: var(--ml-border-subtle) !important;\n}\n[class*=\"sc-massive-actions-toolbar__separator\"],\n[class*=\"sc-massive-actions-toolbar\"] [class*=\"separator\"] {\n  background-color: var(--ml-border) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* ---- Pills, badges and hover affordances ------------------------------ */\n.sll-list-rounded-pills,\n[class*=\"sll-list-rounded-pills\"] {\n  background-color: transparent !important;\n  color: var(--ml-text-secondary) !important;\n}\n.sll-list-rounded-pills__label,\n[class*=\"sll-list-rounded-pills__label\"] {\n  color: var(--ml-text-secondary) !important;\n}\n.sc-hover-button,\n[class*=\"sc-hover-button\"] {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n.sc-hover-button__text,\n[class*=\"sc-hover-button__text\"] {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sc-hover-button\"]:hover {\n  background-color: var(--ml-surface-3) !important;\n}\n\n/* ---- Generic text inside the seller shell -----------------------------\n   The hub emits bare <span>/<p> nodes without classes for table cells, which\n   is where the remaining dark text came from. Scoped to the seller prefixes so\n   nothing global is introduced. */\n[class*=\"sll-\"] span,\n[class*=\"sll-\"] p,\n[class*=\"sc-header-listing\"] span,\n[class*=\"sc-task-card\"] span,\n[class*=\"sc-task-card\"] p,\n[class*=\"sc-massive-actions\"] span {\n  color: inherit !important;\n}\n[class*=\"sll-list\"] a {\n  color: var(--ml-blue) !important;\n}\n[class*=\"sll-\"] table,\n[class*=\"sll-\"] th,\n[class*=\"sll-\"] td {\n  border-color: var(--ml-border-subtle) !important;\n  color: var(--ml-text-primary) !important;\n}\n\n/* ---- Inputs and selects in the seller hub ----------------------------- */\n[class*=\"sll-\"] input,\n[class*=\"sll-\"] select,\n[class*=\"sll-\"] textarea,\n[class*=\"sc-header-listing\"] input,\n[class*=\"sc-massive-actions\"] input {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n  color: var(--ml-text-primary) !important;\n}\n/* \"Filtrar y ordenar\" keeps its own dark colour through the hover-button\n   wrapper, so the plain `.sc-hover-button__text` rule loses. */\n.sll-list-filter-button,\n[class*=\"sll-list-filter-button\"],\n[class*=\"sll-list-filter-button\"] [class*=\"sc-hover-button__text\"],\n[class*=\"sll-list-navbar\"] [class*=\"sc-hover-button\"],\n[class*=\"sll-list-navbar\"] [class*=\"sc-hover-button__text\"] {\n  color: var(--ml-text-primary) !important;\n}\n[class*=\"sll-list-filter-button\"] {\n  background-color: var(--ml-surface-2) !important;\n  border-color: var(--ml-border) !important;\n}\n\n/* ===== 98-late-fixes.css ===== */\n/* ============================================================================\r\n   98-late-fixes.css — third verification pass.\r\n   Everything here was measured on a real `/p/MCO*` page AFTER 70-pdp.css and\r\n   95-misc.css were applied: the SEO footer at the bottom of long pages, the\r\n   review summary/translation prefix, the bare <a> elements inside the category\r\n   mega-menu, and MELI's *semantic* colour-modifier family.\r\n   ========================================================================== */\r\n\r\n/* MELI's ui-pdp-color--* family is not only BLACK/GRAY: it also uses semantic\r\n   suffixes (TEXT_PRIMARY, TEXT_SECONDARY, LINK). Mapping the semantics is the\r\n   most durable of all the hooks, because it expresses intent, not a palette. */\r\n[class*=\"ui-pdp-color--TEXT_PRIMARY\"],\r\n[class*=\"ui-pdp-color--BLACK\"],\r\n[class*=\"ui-pdp-color--DARK\"] {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n[class*=\"ui-pdp-color--TEXT_SECONDARY\"],\r\n[class*=\"ui-pdp-color--GRAY\"],\r\n[class*=\"ui-pdp-color--GREY\"] {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n[class*=\"ui-pdp-color--LINK\"],\r\n[class*=\"ui-pdp-color--ACTION\"] {\r\n  color: var(--ml-blue) !important;\r\n}\r\n\r\n/* ---- SEO footer / \"Destacado en …\" link farm ----------------------------\r\n   MELI appends a large link menu at the end of listing and PDP pages. It is a\r\n   separate namespace (seo-ui-*) with its own title/link/anchor levels. */\r\n.seo-ui-extended-menu,\r\n.seo-ui-extended-menu__container,\r\n.seo-ui-extended-menu__group,\r\n.seo-ui-extended-menu__group__content {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n.seo-ui-extended-menu__header__title,\r\n.seo-ui-extended-menu__group__title,\r\n.seo-ui-extended-menu__group__title__link {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.seo-ui-extended-menu__anchor,\r\n.seo-ui-extended-menu__link {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.seo-ui-extended-menu__anchor:hover,\r\n.seo-ui-extended-menu__link:hover {\r\n  color: var(--ml-blue) !important;\r\n}\r\n.nav-footer-access-content {\r\n  background-color: transparent !important;\r\n}\r\n\r\n/* ---- Review summary ----------------------------------------------------\r\n   \"Resumen de opiniones generado por IA\" + the \"Traducido\" prefix were the\r\n   two leaves still rendering rgba(0,0,0,.9) / .55. */\r\n.ui-review-capability__summary__plain_text__summary_container,\r\n.ui-review-capability__summary__plain_text__sum,\r\n.ui-review-capability__summary__plain_text,\r\n.ui-review-capability__summary__description__text,\r\n.ui-review-capability__summary__description__title {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.ui-review-capability-comments__comment__content__see-original-prefix,\r\n.ui-review-capability-comments__comment__content__see-original {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.ui-review-capability__summary {\r\n  background-color: var(--ml-surface-1) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n\r\n/* ---- Category mega-menu: elements without a class ----------------------\r\n   The panel header (\"Tecnología\") and the <li><a> rows carry no class at all,\r\n   so they can only be reached structurally. */\r\n.nav-categs-detail__header,\r\n.nav-categs-detail__title {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.nav-categs-detail li a,\r\n.nav-categs-detail__content li a,\r\n.nav-categs-detail__item li a {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.nav-categs-detail li a:hover,\r\n.nav-categs-detail__content li a:hover {\r\n  color: var(--ml-blue) !important;\r\n}\r\n\r\n/* ---- Footer catch-all --------------------------------------------------\r\n   Last resort for the plain <a> elements MELI writes without classes. */\r\nfooter a,\r\n.nav-footer a,\r\n[class*=\"nav-footer-access\"] a {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\nfooter a:hover,\r\n.nav-footer a:hover {\r\n  color: var(--ml-blue) !important;\r\n}\r\n/* ---- Rating histogram (\"5 ★ … 1 ★\") ------------------------------------\r\n   The bars are NOT <progress>: they are a div (track) and a span (fill) painted\r\n   with a background-image gradient, which is why neither `background-color` nor\r\n   `::-webkit-progress-*` rules had any effect. Element type is the discriminator:\r\n   div = track, span = fill. */\r\nli.ui-review-capability-rating__level div[class*=\"progress\"],\r\nli.ui-review-capability-rating__level [class*=\"__progress-container\"] {\r\n  background-color: var(--ml-surface-3) !important;\r\n  background-image: none !important;\r\n  border-radius: 4px !important;\r\n}\r\nli.ui-review-capability-rating__level span[class*=\"progress\"],\r\nli.ui-review-capability-rating__level [class*=\"__progress-fill\"] {\r\n  background-color: var(--ml-yellow) !important;\r\n  background-image: none !important;\r\n  border-radius: 4px !important;\r\n}\r\nli.ui-review-capability-rating__level [class*=\"__value\"],\r\nli.ui-review-capability-rating__level [class*=\"__value\"] span {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\nli.ui-review-capability-rating__level [class*=\"__column\"],\r\nli.ui-review-capability-rating__level [class*=\"__column\"] span,\r\nul.ui-review-capability-rating {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n/* Star glyph next to each level number: ASCII star (U+2605) or an injected\r\n   icon, either way it must be brand yellow, not body text. */\r\nli.ui-review-capability-rating__level [class*=\"__column\"]::after,\r\nli.ui-review-capability-rating__level [class*=\"__level-star\"],\r\nli.ui-review-capability-rating__level svg {\r\n  color: var(--ml-yellow) !important;\r\n  fill: var(--ml-yellow) !important;\r\n}\r\n\r\n/* ---- Footer accessibility switch ---------------------------------------\r\n   `#nav-footer-access-switch` is a classless <button> (\"Más información\") in\r\n   the footer accessibility band; the only handle is its id. */\r\n#nav-footer-access-switch,\r\n.nav-footer-access button,\r\n[class*=\"nav-footer-access\"] button {\r\n  background-color: var(--ml-surface-2) !important;\r\n  border-color: var(--ml-border) !important;\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.nav-footer-access,\r\n[class*=\"nav-footer-access\"] {\r\n  background-color: var(--ml-surface-1) !important;\r\n  color: var(--ml-text-secondary) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n\r\n/* ---- Andes money amounts must always inherit ---------------------------\r\n   `.andes-money-amount`, `__currency-symbol`, `__fraction` and `__cents` each\r\n   carry their own `rgba(0,0,0,.9)`. MELI's own intent is that the amount takes\r\n   the colour of its container (blue inside a price, muted inside a struck\r\n   original value). Several DIFFERENT pricing components wrap it —\r\n   `.poly-price` on cards, `.ui-search-price` on CPG/supermarket listings — so\r\n   rule-per-component kept missing variants. Forcing `inherit` on the\r\n   primitive is simpler and more durable.\r\n\r\n   MEASURED TRAP: `inherit` alone is not enough. MELI inserts a CLASSLESS\r\n   `<span>` at `rgb(117,117,117)` between the price container and the amount,\r\n   which cuts inheritance and re-darkens the price. That span must be\r\n   neutralised too, otherwise the fix appears to work on PDPs and fails on\r\n   listings. This lives in the last-pass file so nothing re-colours it after. */\r\n.andes-money-amount,\r\n.andes-money-amount__currency,\r\n.andes-money-amount__currency-symbol,\r\n.andes-money-amount__fraction,\r\n.andes-money-amount__cents,\r\n[class*=\"andes-money-amount__fraction\"],\r\n[class*=\"andes-money-amount__currency-symbol\"] {\r\n  color: inherit !important;\r\n}\r\n[class*=\"poly-price__label\"] span,\r\n[class*=\"poly-price__labels\"] span,\r\n[class*=\"ui-search-price__second-line\"] span,\r\n[class*=\"ui-search-price__part\"] span {\r\n  color: inherit !important;\r\n}\r\n\r\n/* The unit/derived price keeps its secondary treatment. */\r\n.poly-price__label,\r\n.polylabel-price,\r\n[class*=\"poly-price__label\"],\r\n[class*=\"polylabel-price\"],\r\n[class*=\"unit-price\"],\r\n[class*=\"price-per-unit\"] {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* CPG lead-time / availability label (\"Disponible en 14 días\"). */\r\n.poly-component__manufacturing-time,\r\n[class*=\"manufacturing-time\"],\r\n[class*=\"poly-component__availability\"] {\r\n  color: var(--ml-text-muted) !important;\r\n}\r\n\r\n/* SEO info box below listings. */\r\n[class*=\"seo-ui-info-text-box\"] {\r\n  background-color: var(--ml-surface-1) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n[class*=\"seo-ui-info-text-box\"] [class*=\"__title\"],\r\n[class*=\"seo-ui-info-text-box\"] h2,\r\n[class*=\"seo-ui-info-text-box\"] h3 {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n\r\n/* ---- Offer countdown ---------------------------------------------------\r\n   `poly-countdown` renders each digit in its own box plus a \":\" separator.\r\n   The light theme paints the digits dark on a white box; once the box goes\r\n   dark the digits vanish. Both the box and the glyph need the dark-theme\r\n   pairing, and the separator must follow too or the clock reads as \"0 0\". */\r\n.poly-countdown,\r\n[class*=\"poly-countdown\"] {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.poly-countdown__digit,\r\n[class*=\"poly-countdown__digit\"] {\r\n  background-color: var(--ml-surface-3) !important;\r\n  border-color: var(--ml-border) !important;\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n.poly-countdown__separator,\r\n[class*=\"poly-countdown__separator\"] {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n\r\n/* ---- CPG (supermarket) product pages -----------------------------------\r\n   `ui-cpg-*` is the Consumer-Packaged-Goods subsystem used by every\r\n   /up/MCOU* product page (arroz, bebidas, aseo, farmacia). It ships its own\r\n   reset and its own department side menu, which is why it survives the\r\n   generic `.ui-pdp-*` rules: 47 department links + 7 link names stayed dark. */\r\n.ui-cpg--reset,\r\n[class*=\"ui-cpg--reset\"] {\r\n  background-color: var(--ml-surface-0) !important;\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n[class*=\"ui-cpg__department-menu\"] {\r\n  background-color: var(--ml-surface-1) !important;\r\n  border-color: var(--ml-border-subtle) !important;\r\n}\r\n.ui-cpg__department-menu-list-item-link,\r\n[class*=\"ui-cpg__department-link-name\"],\r\n[class*=\"ui-cpg__department-menu-list-item\"] a,\r\n[class*=\"ui-cpg__department-menu\"] a {\r\n  color: var(--ml-text-secondary) !important;\r\n}\r\n.ui-cpg__department-link-name,\r\n[class*=\"ui-cpg__department-link-name\"] {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n[class*=\"ui-cpg__department-menu\"] a:hover,\r\n[class*=\"ui-cpg__department-link-name\"]:hover {\r\n  color: var(--ml-blue) !important;\r\n}\r\n/* The department menu heading (\"Departamentos\"). */\r\n[class*=\"ui-cpg__department\"] [class*=\"__title\"],\r\n[class*=\"ui-cpg__department-menu\"] h2,\r\n[class*=\"ui-cpg__department-menu\"] h3 {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n/* Remaining generic paragraphs inside the CPG shell. */\r\n[class*=\"ui-cpg\"] p,\r\n[class*=\"ui-cpg\"] li {\r\n  color: var(--ml-text-primary) !important;\r\n}\r\n\r\n/* ---- Product thumbnail letterbox: must NOT be our dark surface ---------\r\n   Root cause of three separate reports that looked unrelated:\r\n\r\n     /preguntas/comprador  .andes-thumbnail--48 around img.sc-basic-information__img\r\n     /my_purchases/list    .andes-thumbnail--32 around img styles__Image-*\r\n     /gz/cart/v2           .cl-image-label__overlay over the photo\r\n\r\n   A thumbnail is a LETTERBOX: MELI sizes the box to the product image's aspect\r\n   and paints the leftover area white. Product photos are shot on white, so the\r\n   box must stay light or the photo stops reading as a product and starts\r\n   reading as a hole — which is precisely \"las miniaturas se ven negras\".\r\n\r\n   Measured on /preguntas: img box 48x64 inside a 50x50 box with\r\n   `overflow: hidden`. My `[class*=\"andes-thumbnail\"] { background-color:\r\n   var(--ml-surface-2) }` painted that leftover band near-black (#1f242c), so\r\n   every thumbnail became a dark rectangle with a thin sliver of photo.\r\n\r\n   Fix: thumbnails keep a light letterbox, in a softened off-white so it does\r\n   not become a lightbulb on a dark page. The photo is never recoloured; only\r\n   the empty band around it is light, exactly as MELI intended. */\r\n.andes-thumbnail,\r\n.andes-thumbnail-container,\r\n[class*=\"andes-thumbnail\"],\r\n[class*=\"styles__Thumbnail\"],\r\n.cl-image-label__container {\r\n  background-color: #e9edf2 !important;\r\n  background-image: none !important;\r\n}\r\n\r\n/* Inside a BEM thumbnail the image already carries its own white plate; make\r\n   the primitive's own plate match so no seam appears. */\r\n.andes-thumbnail__image,\r\n[class*=\"andes-thumbnail\"] > img {\r\n  background-color: #e9edf2 !important;\r\n}\r\n\r\n/* The photos themselves are never filtered here — dimming is owned by\r\n   --ml-img-dim in base.css and applies to card hero images, not thumbnails,\r\n   where a 30-50 px box cannot afford the loss of contrast. */\r\n.andes-thumbnail img,\r\n[class*=\"andes-thumbnail\"] img,\r\n[class*=\"styles__Thumbnail\"] img {\r\n  filter: none !important;\r\n  opacity: 1 !important;\r\n  visibility: visible !important;\r\n}\n\n/* ===== 99-iframes.css ===== */\n/* ===========================================================================\r\n   99-iframes.css — widgets that MELI renders inside same-origin iframes\r\n   ===========================================================================\r\n\r\n   WHY THIS FILE EXISTS\r\n   --------------------\r\n   Some MELI panels are not part of the host document. They are separate\r\n   documents served from their own routes and mounted with <iframe src=…>:\r\n\r\n     /notifications/center/widget?modeless_box_version=…   (bell panel)\r\n     …and whatever else MELI decides to split out next.\r\n\r\n   Consequences, all measured:\r\n     • Our rules never reach them. An injected <style> lives in the host\r\n       document; an iframe has its own document, its own styleSheets and its\r\n       own cascade. No amount of `!important` crosses that boundary, exactly\r\n       like Shadow DOM.\r\n     • They ship their OWN class system. The notification widget uses\r\n       `hub-*` / `hub-layout-*` / `notification-*` / `notification-item-*` /\r\n       `category-tabs-*` — none of which appear anywhere else in the theme,\r\n       so every earlier fix pass ignored them.\r\n     • They start from a bare white `body` (#fff), so without rules here they\r\n       render as a fully white card in the middle of the dark header.\r\n\r\n   Stylus and most UserCSS managers DO inject into same-origin iframes, which\r\n   is what makes this fixable at all: the widget is served from\r\n   mercadolibre.com.co, the same origin as the page that embeds it, and the\r\n   domain list of the document wrapper at the top of this file already\r\n   matches it.\r\n\r\n   !! NEVER NAME THE DOCUMENT-WRAPPER AT-RULE IN A COMMENT !!\r\n   Stylus splits a UserCSS into sections with a plain text search for that\r\n   at-rule; it does not know about comments. A mention in a CSS comment block\r\n   creates a phantom section boundary, which unbalances the braces and makes\r\n   the ENTIRE style stop applying on every page -- the exact failure observed as\r\n   \"nothing applies on /ayuda, /ofertas, /c/ropa-y-accesorios\". tools/build.mjs\r\n   now fails the build if the token appears more than once, so this cannot\r\n   regress silently.\r\n\r\n   RELATED TRAP, PAID FOR TWICE: never write the two-character sequence that\r\n   CLOSES a CSS comment inside one. Writing it to mean \"a comment\" ends the\r\n   comment early, and every following line is parsed as CSS -- which is exactly\r\n   how the selector fragments further down became syntax errors. Describe a\r\n   comment in words instead.\r\n\r\n   SCOPE NOTE\r\n   ----------\r\n   These rules are intentionally written against the *generic* names\r\n   (`hub-header`, `notification-item__*`, `category-tabs`). Per the hard rule\r\n   in 92-landings.css we never widen `[class*=\"…\"]` to a prefix that could\r\n   swallow a content class such as `…-image` or `…__overlay`; the attribute\r\n   selectors below are anchored at `^=` (prefix) or on an exact token so the\r\n   blast radius stays inside the widget.\r\n\r\n   If a future pass finds another white iframe, map its prefixes and add a\r\n   section here — do not add page-specific chains to the host files.\r\n   =========================================================================== */\r\n\r\n/* ---- Notification centre widget (hub-* / notification-* ) ---------------- */\r\n\r\n/* The widget's own document. `:root` carries our token defaults because the\r\n   tokens travel with the stylesheet, but the widget's body paints its own\r\n   white background over whatever we set on the root. */\r\nhtml,\r\nbody {\r\n  background-color: var(--ml-surface-1, #181c22) !important;\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n\r\n/* Widget chrome: header bar, tab strip, scroll rail, footer. */\r\n[class^=\"hub-header\"],\r\n[class^=\"hub-layout\"],\r\n[class^=\"hub-footer\"],\r\n[class^=\"category-tabs\"],\r\n[class^=\"channels-log\"],\r\n[class^=\"modeless-box\"] {\r\n  background-color: var(--ml-surface-1, #181c22) !important;\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n  border-color: var(--ml-border-subtle, #242a33) !important;\r\n}\r\n\r\n/* Header title (\"Notificaciones\") ships as `#333` inside the iframe. */\r\n[class^=\"hub-header\"] :is(h1, h2, h3, h4, span, div, p),\r\n[class^=\"hub-header__title\"] {\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n\r\n/* ---- Tabs (Todo / Ventas / Compras …) ----------------------------------- */\r\n/* MELI reuses `andes-tabs` here, but the unscoped `.andes-tab__link` rules in\r\n   50-coverage.css are written for the host document's padding rhythm; inside\r\n   the widget only the colours need to land. */\r\n[class^=\"category-tabs\"] :is(button, a, span, li),\r\n[class^=\"andes-tab\"] {\r\n  color: var(--ml-text-secondary, #a9b3c1) !important;\r\n  border-color: transparent !important;\r\n  background-color: transparent !important;\r\n}\r\n[class^=\"category-tabs\"] :is(button, a, span, li)[class*=\"active\"],\r\n[class^=\"category-tabs\"] :is(button, a, span, li)[aria-selected=\"true\"] {\r\n  color: var(--ml-blue, #5b9bff) !important;\r\n  border-color: var(--ml-blue, #5b9bff) !important;\r\n}\r\n/* The bare `<span>Ventas</span>` label MELI emits unclassified at rgb(115,115,115). */\r\n[class^=\"category-tabs\"] > span,\r\n[class^=\"category-tabs\"] > span * {\r\n  color: var(--ml-text-secondary, #a9b3c1) !important;\r\n}\r\n\r\n/* ---- Notification rows -------------------------------------------------- */\r\n[class^=\"notification-item\"] {\r\n  background-color: transparent !important;\r\n  border-color: var(--ml-border-subtle, #242a33) !important;\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n[class^=\"notification-item\"]:hover {\r\n  background-color: var(--ml-surface-2, #1f242c) !important;\r\n}\r\n[class^=\"notification-item__content\"],\r\n[class^=\"notification-item__body\"],\r\n[class^=\"notification-item__wrapper\"] {\r\n  background-color: transparent !important;\r\n}\r\n/* Unread rows carry a tint + bolder title; keep the emphasis, on dark. */\r\n[class^=\"notification-item\"][class*=\"unread\"],\r\n[class^=\"notification-item--unread\"] {\r\n  background-color: var(--ml-surface-2, #1f242c) !important;\r\n}\r\n[class^=\"notification-item\"][class*=\"unread\"] :is(a, span, p, div),\r\n[class^=\"notification-item--unread\"] :is(a, span, p, div) {\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n\r\n/* Row typography: title (rgba(0,0,0,.9)), date and body (rgba(0,0,0,.55)).\r\n   These are exactly the three literals 30-text.css maps on the host page, so\r\n   the same mapping applies — the iframe just never received it. */\r\n[class^=\"notification-item__title\"] {\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n[class^=\"notification-item__title-date\"],\r\n[class^=\"notification-item__date\"] {\r\n  color: var(--ml-text-muted, #7c8794) !important;\r\n}\r\n[class^=\"notification-item__text\"],\r\n[class^=\"notification-item__description\"],\r\n[class^=\"notification-item__subtitle\"] {\r\n  color: var(--ml-text-secondary, #a9b3c1) !important;\r\n}\r\n[class^=\"notification-item\"] :is(h1, h2, h3, h4, strong, b) {\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n[class^=\"notification-item\"] a {\r\n  color: var(--ml-blue, #5b9bff) !important;\r\n}\r\n\r\n/* Delete/dismiss affordance: light theme is a #f0f0f0 pill with a dark glyph. */\r\n[class^=\"notification-item__delete\"] {\r\n  background-color: var(--ml-surface-3, #262c35) !important;\r\n  color: var(--ml-text-secondary, #a9b3c1) !important;\r\n  border-color: var(--ml-border-subtle, #242a33) !important;\r\n}\r\n[class^=\"notification-item__delete\"]:hover {\r\n  background-color: var(--ml-surface-4, #2e3540) !important;\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n\r\n/* Thumbnails inside rows: the widget paints them #fff as a letterbox behind\r\n   transparent PNGs, which reads as a white hole on the dark list. */\r\n[class^=\"notification-item\"] [class^=\"andes-thumbnail\"],\r\n[class^=\"notification-item\"] [class^=\"andes-image\"],\r\n[class^=\"notification-item\"] img {\r\n  background-color: var(--ml-surface-2, #1f242c) !important;\r\n  border-color: var(--ml-border-subtle, #242a33) !important;\r\n}\r\n\r\n/* ---- Generic safety net for any future iframe --------------------------- */\r\n/* Any widget MELI ships in an iframe still starts from a white body. These\r\n   two rules make the *default* look correct even before a widget-specific\r\n   pass exists, so a new panel shows up as slightly-bright rather than as a\r\n   glowing white rectangle. */\r\n:root:not([data-ml-theme]) body:not([class]) {\r\n  background-color: var(--ml-surface-1, #181c22) !important;\r\n}\r\n\r\n/* The `noscript` element reports `color: rgb(0,0,0)` in the widget document;\r\n   it never renders, so leave it alone rather than chasing it in audits. */\r\n\r\n/* ---- Address hub widget (andes-ui-* variant) ----------------------------\r\n   The address picker mounted by the header link is another same-origin\r\n   iframe (/addresses/v3/navigation/hub) and it uses a THIRD generation of the\r\n   design system: `andes-ui-*` instead of `andes-*`. All earlier passes wrote\r\n   `andes-*` selectors, so nothing landed here and the dialog body — plus its\r\n   fixed footer bar, `andes-ui-fixed-footer` at rgb(255,255,255) — rendered\r\n   white with rgba(0,0,0,.9) text on top.\r\n\r\n   `[class^=\"andes-ui\"]` is safe to use as a prefix here (unlike the substring\r\n   problem in 92-landings.css): it is anchored at the start of a class token\r\n   and the only MELI classes beginning with `andes-ui` are this generation's\r\n   primitives. */\r\nhtml,\r\nbody {\r\n  background-color: transparent !important; /* the host dialog paints behind */\r\n}\r\n\r\n[class^=\"andes-ui\"] {\r\n  border-color: var(--ml-border-subtle, #242a33) !important;\r\n}\r\n\r\n/* Structural shells of this generation. */\r\n[class^=\"layout\"],\r\n[class^=\"content\"],\r\n[class^=\"andes-ui-fixed\"],\r\n[class^=\"andes-ui-dismiss\"] {\r\n  background-color: var(--ml-surface-4, #2e3540) !important;\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n\r\n/* Typography primitives carry the text colour directly, at\r\n   rgba(0,0,0,.9) / rgba(0,0,0,.55). */\r\n[class^=\"andes-ui-typography\"] {\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n[class*=\"andes-ui-typography-body\"],\r\n[class*=\"andes-progress-indicator\"] {\r\n  color: var(--ml-text-secondary, #a9b3c1) !important;\r\n}\r\n\r\n/* Footer bar with the confirm/cancel buttons. */\r\n[class^=\"andes-ui-fixed-footer\"],\r\n[class*=\"andes-ui-fixed\"][class*=\"footer\"] {\r\n  background-color: var(--ml-surface-4, #2e3540) !important;\r\n  border-top: 1px solid var(--ml-border-subtle, #242a33) !important;\r\n  box-shadow: none !important;\r\n}\r\n\r\n/* Buttons: keep brand fills, only retint the neutral (secondary) variant. */\r\n[class^=\"andes-ui-button\"] {\r\n  border-color: var(--ml-border, #2f3742) !important;\r\n}\r\n[class*=\"andes-ui-button\"][class*=\"secondary\"],\r\n[class*=\"andes-ui-button\"][class*=\"neutral\"],\r\n[class*=\"andes-ui-button\"][class*=\"outline\"] {\r\n  background-color: var(--ml-surface-2, #1f242c) !important;\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n}\r\n\r\n/* Dismiss control (the × ) and any link inside the widget. */\r\n[class*=\"andes-ui-dismiss\"] {\r\n  background-color: transparent !important;\r\n  color: var(--ml-text-secondary, #a9b3c1) !important;\r\n}\r\n[class^=\"andes-ui\"] a,\r\n[class^=\"andes-ui\"] a * {\r\n  color: var(--ml-blue, #5b9bff) !important;\r\n}\r\n\r\n/* Inputs (address search / new address form). */\r\n[class^=\"andes-ui\"] :is(input, textarea, select) {\r\n  background-color: var(--ml-surface-2, #1f242c) !important;\r\n  color: var(--ml-text-primary, #e3e8ef) !important;\r\n  border-color: var(--ml-border, #2f3742) !important;\r\n}\r\n[class^=\"andes-ui\"] :is(input, textarea)::placeholder {\r\n  color: var(--ml-text-disabled, #5a6472) !important;\r\n}\r\n\n/* ---- Help centre chat widget (/chat) -----------------------------------\n   Reached by clicking \"Contactanos\" on /ayuda; the panel is a same-origin\n   IFRAME whose src is\n     /chat?flavor=mlcx&origin=portal&hideHeader=true&andes_ui=restyled\n\n   Because it is same-origin AND on the same domain, the wrapper at-rule\n   already matches it, so these rules land without any extra plumbing. That\n   is why its <body> was already surface-1 while the panel stayed white: only\n   the body was covered, never the panel's own vocabulary.\n\n   Measured on the live widget:\n\n     .chat-container(.--navbar-hidden)       rgb(255,255,255)   340x556\n     .conversation-sidebar__content          rgb(255,255,255)   340x556\n     .voice-transcript-sidebar__content      rgb(255,255,255)   306x556\n     .voice-transcript-sidebar__list         rgb(247,248,250)\n     button.welcome-item  x3                 rgb(244,245,249)\n     .welcome-greeting__line                 dark, unreadable\n     .voice-transcript-sidebar__title        dark, unreadable\n\n   Text primitives are shared with the rest of the site (andes-ui-typography,\n   andes-typography), so they were already themed; only the containers and the\n   two widget-specific headings needed work. */\n.chat-container,\n[class*=\"chat-container\"],\n[class*=\"conversation-sidebar__content\"],\n[class*=\"voice-transcript-sidebar__content\"],\n[class*=\"voice-transcript-sidebar__list\"],\n[class*=\"chat-pane\"],\n[class*=\"chat-main\"],\n[class*=\"chat-messages\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  background-image: none !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n\n/* The three starter prompts: light chips that became unreadable once their\n   labels inherited the dark-theme text colour. */\n[class*=\"welcome-item\"],\n[class*=\"welcome-starter\"] {\n  background-color: var(--ml-surface-2, #1f242c) !important;\n  background-image: none !important;\n  border-color: var(--ml-border, #242a33) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"welcome-item\"]:hover,\n[class*=\"welcome-starter\"]:hover {\n  background-color: var(--ml-surface-3, #262c35) !important;\n}\n\n/* Widget-specific headings that carry their own black text. */\n[class*=\"welcome-greeting\"],\n[class*=\"voice-transcript-sidebar__title\"],\n[class*=\"sidebar-state-view\"] {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"welcome-greeting\"] * {\n  color: inherit !important;\n  -webkit-text-fill-color: inherit !important;\n}\n\n/* Input row and the floating upload/record affordances. */\n[class*=\"new-chat-input\"],\n[class*=\"chat-input\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  border-color: var(--ml-border, #242a33) !important;\n}\n[class*=\"new-chat-input\"] input,\n[class*=\"new-chat-input\"] textarea,\n[class*=\"chat-input\"] input,\n[class*=\"chat-input\"] textarea {\n  background-color: var(--ml-input-bg, #12151a) !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"new-chat-input\"] input::placeholder,\n[class*=\"chat-input\"] input::placeholder {\n  color: var(--ml-text-muted, #7c8794) !important;\n}\n\n/* reCAPTCHA badge is a third-party white card pinned to the widget corner;\n   it is MELI's obligation to show it, so leave its own paint untouched and\n   only stop it from glowing against the dark panel. */\n[class*=\"grecaptcha\"] {\n  opacity: 0.85 !important;\n}\n\n/* ---- Floating chat popup shell (host document) -------------------------\n   The chat panel is TWO pieces, and only one of them is the iframe:\n\n     section.floating-contact-popup(--open)     rgb(255,255,255)  340x620\n       div.floating-contact-popup__header                       340x64\n         div.andes-ui-header__content_wrapper  rgb(255,255,255)  340x64\n         div.andes-ui-header__content\n       div.floating-contact-popup__body  -> contains the /chat iframe\n\n   The header bar — with the compose, history, \"Asistente\" label, expand and\n   close controls — lives HERE, in the page, not inside the frame. That is why\n   theming the iframe left a bright white bar floating above the dark panel,\n   with light-on-white labels barely visible.\n\n   The header itself is the generic `andes-ui-header` primitive, so it is\n   themed as a primitive rather than as a widget one-off: any future MELI\n   surface built from the same component inherits the fix. */\n.floating-contact-popup,\n[class*=\"floating-contact-popup\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  background-image: none !important;\n  border-color: var(--ml-border, #242a33) !important;\n  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.55) !important;\n}\n[class*=\"floating-contact-popup\"] [class*=\"__header\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  background-image: none !important;\n  border-color: var(--ml-border, #242a33) !important;\n}\n[class*=\"floating-contact-popup\"] [class*=\"__body\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  background-image: none !important;\n}\n/* The header's own labels/buttons, which MELI paints for a white bar. */\n[class*=\"floating-contact-popup\"] [class*=\"andes-ui-header\"] {\n  background-color: var(--ml-surface-1, #181c22) !important;\n  background-image: none !important;\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  -webkit-text-fill-color: var(--ml-text-primary, #e3e8ef) !important;\n}\n[class*=\"floating-contact-popup\"] [class*=\"andes-ui-header\"] * {\n  color: inherit !important;\n  -webkit-text-fill-color: inherit !important;\n}\n[class*=\"floating-contact-popup\"] button,\n[class*=\"floating-contact-popup\"] [class*=\"icon\"] {\n  color: var(--ml-text-secondary, #a9b3c1) !important;\n}\n[class*=\"floating-contact-popup\"] button:hover {\n  color: var(--ml-text-primary, #e3e8ef) !important;\n  background-color: var(--ml-surface-3, #262c35) !important;\n}\n";
  document.head.appendChild(s);
  /* Wait two animation frames: appendChild only invalidates style, and a
     getComputedStyle in the same task can still answer from the OLD computed
     tree. Measuring too early silently reports the pre-injection colours. */
  await new Promise((r) => requestAnimationFrame(() => requestAnimationFrame(r)));

  const parse = (c) => { const m = c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)(?:,\s*([\d.]+))?\)/); return m ? { r: +m[1], g: +m[2], b: +m[3], a: m[4] === undefined ? 1 : +m[4] } : null; };
  const isDark = (c) => { const v = parse(c); return !!v && v.a > 0.3 && v.r < 135 && v.g < 135 && v.b < 135; };
  const isLight = (c) => { const v = parse(c); return !!v && v.a > 0.4 && v.r > 232 && v.g > 232 && v.b > 232; };
  const darkText = new Map(), lightBg = new Map();
  for (const el of document.querySelectorAll('body *')) {
    if (el.closest('.andes-visually-hidden,[class*=visually-hidden]')) continue;
    const cs = getComputedStyle(el);
    if (cs.display === 'none' || cs.visibility === 'hidden') continue;
    const key = (el.getAttribute('class') || el.tagName.toLowerCase()).split(/\s+/).slice(0, 2).join('.').slice(0, 46);
    if (el.children.length === 0 && el.textContent.trim() && isDark(cs.color) && isDark(cs.webkitTextFillColor)) darkText.set(key, (darkText.get(key) || 0) + 1);
    if (isLight(cs.backgroundColor) && !el.closest('img,picture,[class*=thumbnail],[class*=picture]')) lightBg.set(key, (lightBg.get(key) || 0) + 1);
  }
  const top = (m) => [...m.entries()].sort((a, b) => b[1] - a[1]).slice(0, 12);
  const total = [...darkText.values()].reduce((a, b) => a + b, 0) + [...lightBg.values()].reduce((a, b) => a + b, 0);
  return JSON.stringify({ url: location.href, title: document.title.slice(0, 60), problems: total, darkText: top(darkText), lightBg: top(lightBg) });
})()